
    :root {
      --bg: #201d1a;
      --panel: #2f2b27;
      --panel-2: #3b3630;
      --text: #f7f1e6;
      --muted: #cfc3b2;
      --soft: #f0d9b5;
      --board-light: #f0d9b5;
      --board-dark: #b58863;
      --board-light-texture: none;
      --board-dark-texture: none;
      --green: #7fa650;
      --green-dark: #5f7f3a;
      --gold: #e7b65d;
      --blue: #6fa8dc;
      --danger: #d86f62;
      --line: rgba(255, 255, 255, 0.13);
      --shadow: 0 22px 60px rgba(0, 0, 0, 0.32);
      --radius: 8px;
      --max: 1380px;
      --move-speed: 140ms;
      --ui-fast: 160ms;
      --ui-standard: 220ms;
      --last-move-light: rgba(231, 182, 93, 0.42);
      --last-move-dark: rgba(231, 182, 93, 0.35);
      --board-frame-bg: rgba(33, 26, 18, 0.78);
      --board-frame-gradient: linear-gradient(135deg, rgba(255, 248, 237, 0.3), rgba(231, 182, 93, 0.64), rgba(127, 166, 80, 0.42));
      --board-frame-glow: rgba(231, 182, 93, 0.18);
      --board-frame-hover-glow: rgba(231, 182, 93, 0.24);
      --board-frame-outline: rgba(255, 248, 237, 0.08);
      --board-frame-solution-gradient: conic-gradient(from 0deg, rgba(111, 168, 220, 0.95), rgba(231, 182, 93, 0.8), rgba(111, 168, 220, 0.16), rgba(111, 168, 220, 0.95));
      --site-bg-image: radial-gradient(circle at 12% 10%, rgba(231, 182, 93, 0.16), transparent 28%), radial-gradient(circle at 90% 8%, rgba(127, 166, 80, 0.14), transparent 26%);
    }

    body.theme-light {
      --bg: #f6f1e8;
      --panel: #fffaf0;
      --panel-2: #eadfce;
      --text: #211a12;
      --muted: #675b4d;
      --soft: #3b3026;
      --line: rgba(33, 26, 18, 0.14);
    }

    body.board-wood {
      --board-light: #f0d9b5;
      --board-dark: #b58863;
    }

    body.board-marble {
      --board-light: #ede9df;
      --board-dark: #8fa3a8;
    }

    body.board-neon {
      --board-light: #d8fff4;
      --board-dark: #245cff;
    }

    body.board-forest {
      --board-light: #dce8c6;
      --board-dark: #5f7f4a;
    }

    body.board-dragon {
      --board-light: #f7dba7;
      --board-dark: #8f3f2e;
    }

    body.board-sky {
      --board-light: #e9f7ff;
      --board-dark: #5f91c9;
    }

    body.board-ocean {
      --board-light: #d9f2ea;
      --board-dark: #2f7f89;
    }

    body.board-midnight {
      --board-light: #d7caa8;
      --board-dark: #3b3a4f;
    }

    body.board-candy {
      --board-light: #f8d7e9;
      --board-dark: #6aa6a8;
    }

    body.board-slate {
      --board-light: #d7dde3;
      --board-dark: #56616b;
    }

    body.board-sunrise {
      --board-light: #ffe2b8;
      --board-dark: #c6654b;
    }

    body.board-theme-animated .puzzle-board-wrap {
      animation: boardThemeGlowPulse 5.8s ease-in-out infinite;
    }

    @keyframes boardThemeGlowPulse {
      0%, 100% { box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28), 0 0 18px color-mix(in srgb, var(--board-theme-glow, var(--board-frame-glow)) 28%, transparent); }
      50% { box-shadow: 0 20px 48px rgba(0, 0, 0, 0.32), 0 0 30px color-mix(in srgb, var(--board-theme-glow, var(--board-frame-glow)) 42%, transparent); }
    }

    body.board-sakura {
      --board-light: #ffe8ef;
      --board-dark: #b86f8c;
    }

    body.board-royal {
      --board-light: #f6e6b9;
      --board-dark: #7b4f9e;
    }

    body.board-emerald {
      --board-light: #e2f4d3;
      --board-dark: #2f8a67;
    }

    body.board-crystal {
      --board-light: #eefbff;
      --board-dark: #6fa8dc;
    }

    body.board-obsidian {
      --board-light: #cfd5d8;
      --board-dark: #2e343b;
    }

    body.board-aurora {
      --board-light: #e7fff2;
      --board-dark: #6e6bd9;
    }

    body.board-cosmic {
      --board-light: #ded7ff;
      --board-dark: #35245f;
    }

    body.board-divine {
      --board-light: #fff7cf;
      --board-dark: #b36f2d;
    }

    body.lastmove-lime {
      --last-move-light: rgba(170, 220, 95, 0.48);
      --last-move-dark: rgba(170, 220, 95, 0.38);
    }

    body.lastmove-sky {
      --last-move-light: rgba(111, 168, 220, 0.5);
      --last-move-dark: rgba(111, 168, 220, 0.4);
    }

    body.lastmove-rose {
      --last-move-light: rgba(255, 139, 147, 0.5);
      --last-move-dark: rgba(255, 139, 147, 0.4);
    }

    body.lastmove-violet {
      --last-move-light: rgba(174, 135, 255, 0.5);
      --last-move-dark: rgba(174, 135, 255, 0.4);
    }

    body.high-contrast {
      --line: rgba(255, 255, 255, 0.28);
      --last-move-light: rgba(255, 238, 88, 0.54);
      --last-move-dark: rgba(255, 238, 88, 0.44);
    }

    body.high-contrast .puzzle-board-wrap,
    body.high-contrast .mini-board {
      box-shadow:
        0 18px 42px rgba(0, 0, 0, 0.42),
        0 0 0 2px rgba(255, 255, 255, 0.34),
        0 0 24px var(--board-frame-glow);
    }

    body.high-contrast .play-square.selected {
      box-shadow: inset 0 0 0 5px rgba(255, 238, 88, 0.95), inset 0 0 0 2px rgba(0, 0, 0, 0.45);
    }

    body.high-contrast .play-square.legal::after {
      background: rgba(255, 255, 255, 0.62);
      box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.35);
    }

    body.high-contrast .play-square.capture::after {
      border-color: rgba(255, 90, 90, 0.94);
      box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.42);
    }

    body.coords-off .coordinates {
      display: none;
    }

    body.piece-letter .puzzle-square {
      font-family: Inter, ui-sans-serif, system-ui, sans-serif;
      font-weight: 1000;
    }

    body.piece-letter .piece-symbol {
      font-family: Inter, ui-sans-serif, system-ui, sans-serif;
      font-weight: 1000;
    }

    body.speed-slow {
      --move-speed: 260ms;
    }

    body.speed-fast {
      --move-speed: 70ms;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--site-bg-image), var(--bg);
      background-attachment: fixed;
      background-position: center;
      background-size: cover;
      color: var(--text);
      font-family: var(--cq-font-sans, "Manrope", Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
      line-height: var(--cq-leading-body, 1.58);
      transition: background 260ms ease, color 160ms ease;
    }

    body::before {
      content: "";
      position: fixed;
      inset: 0;
      z-index: -2;
      pointer-events: none;
      background: var(--site-bg-image), var(--bg);
      background-attachment: fixed;
      background-size: cover;
      transition: opacity 320ms ease, filter 320ms ease;
    }

    body::after {
      content: "";
      position: fixed;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 0%, rgba(255, 248, 237, 0.055), transparent 34%),
        linear-gradient(180deg, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.24));
    }

    body[data-background-key="galaxy"]::before,
    body[data-background-key="space"]::before,
    body[data-background-key="aurora"]::before,
    body[data-background-key="cyberpunk"]::before,
    body[data-background-key="neon"]::before {
      animation: siteBackgroundDrift 14s ease-in-out infinite alternate;
    }

    body[data-background-key="galaxy"],
    body[data-background-key="space"],
    body[data-background-key="aurora"],
    body[data-background-key="cyberpunk"],
    body[data-background-key="neon"] {
      animation: siteBackgroundDrift 14s ease-in-out infinite alternate;
    }

    body[data-background-key="rain"]::before {
      animation: siteRainDrift 9s linear infinite;
    }

    body[data-background-key="rain"] {
      animation: siteRainDrift 9s linear infinite;
    }

    body[data-background-key="crystal"]::before,
    body[data-background-key="fantasy"]::before,
    body[data-background-key="royalPalace"]::before,
    body[data-background-key="christmas"]::before,
    body[data-background-key="japaneseGarden"]::before,
    body[data-background-key="halloween"]::before,
    body[data-background-key="medieval"]::before,
    body[data-background-key="volcano"]::before,
    body[data-background-key="snow"]::before,
    body[data-background-key="ocean"]::before {
      animation: sitePremiumAura 12s ease-in-out infinite alternate;
    }

    body[data-background-key="crystal"],
    body[data-background-key="fantasy"],
    body[data-background-key="royalPalace"],
    body[data-background-key="christmas"],
    body[data-background-key="japaneseGarden"],
    body[data-background-key="halloween"],
    body[data-background-key="medieval"],
    body[data-background-key="volcano"],
    body[data-background-key="snow"],
    body[data-background-key="ocean"] {
      animation: sitePremiumAura 12s ease-in-out infinite alternate;
    }

    @keyframes siteBackgroundDrift {
      from { background-position: 0% 0%, 100% 0%, 50% 50%; filter: saturate(1); }
      to { background-position: 8% 4%, 92% 6%, 50% 50%; filter: saturate(1.12); }
    }

    @keyframes siteRainDrift {
      from { background-position: 0 0, 0 0; }
      to { background-position: 0 72px, 0 0; }
    }

    @keyframes sitePremiumAura {
      from { background-position: 0% 0%, 100% 0%, 50% 50%; filter: saturate(1) brightness(1); }
      to { background-position: 5% 5%, 94% 3%, 50% 50%; filter: saturate(1.1) brightness(1.04); }
    }

    body.short-feed-locked {
      overflow: hidden;
    }

    body.theme-swapping::before {
      content: "";
      position: fixed;
      inset: 0;
      z-index: 999;
      pointer-events: none;
      background: rgba(255, 248, 237, 0.08);
      animation: themeFadeWash 360ms ease both;
    }

    @keyframes themeFadeWash {
      from { opacity: 1; }
      to { opacity: 0; }
    }

    body::selection {
      background: var(--gold);
      color: #211a12;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img,
    iframe {
      max-width: 100%;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      border-bottom: 1px solid var(--line);
      background: rgba(32, 29, 26, 0.93);
      backdrop-filter: blur(14px);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 14px;
      width: min(100% - 32px, var(--max));
      margin: 0 auto;
      min-height: 68px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 900;
      letter-spacing: 0;
      white-space: nowrap;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border: 2px solid var(--board-light);
      background:
        linear-gradient(45deg, var(--board-dark) 25%, transparent 25% 75%, var(--board-dark) 75%),
        linear-gradient(45deg, var(--board-dark) 25%, transparent 25% 75%, var(--board-dark) 75%);
      background-color: var(--board-light);
      background-position: 0 0, 9px 9px;
      background-size: 18px 18px;
      border-radius: var(--radius);
      color: #211a12;
      font-size: 0.72rem;
      font-weight: 1000;
      line-height: 1;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      flex: 1 1 520px;
      flex-wrap: nowrap;
      justify-content: center;
      min-width: 0;
      overflow: visible;
      padding: 6px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.04);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }

    .nav-group {
      position: relative;
      display: block;
      flex: 0 0 auto;
    }

    .nav-group-label {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      min-height: 38px;
      padding: 0 12px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 7px;
      background: rgba(0, 0, 0, 0.16);
      color: var(--gold);
      cursor: pointer;
      font: inherit;
      font-size: 0.74rem;
      font-weight: 1000;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      list-style: none;
      transition: background var(--move-speed) ease, color var(--move-speed) ease, transform var(--move-speed) ease;
    }

    .nav-group-label::-webkit-details-marker {
      display: none;
    }

    .nav-group-label::after {
      content: "v";
      color: var(--muted);
      font-size: 0.7rem;
      text-transform: none;
    }

    .nav-group[open] > .nav-group-label,
    .nav-group.is-active-group > .nav-group-label,
    .nav-group-label:hover,
    .nav-group-label:focus-visible {
      color: #10150d;
      background: var(--green);
      outline: none;
      transform: translateY(-1px);
    }

    .nav-menu {
      position: absolute;
      top: calc(100% + 10px);
      left: 0;
      z-index: 30;
      display: grid;
      min-width: 190px;
      gap: 6px;
      padding: 8px;
      border: 1px solid rgba(255, 248, 237, 0.13);
      border-radius: var(--radius);
      background: rgba(38, 34, 30, 0.98);
      box-shadow: 0 18px 36px rgba(0, 0, 0, 0.34);
    }

    .nav-group:last-of-type .nav-menu {
      right: 0;
      left: auto;
    }

    .nav-links a {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 36px;
      padding: 0 11px;
      border-radius: 6px;
      color: var(--muted);
      font-size: 0.84rem;
      font-weight: 900;
      white-space: nowrap;
      transition: background var(--ui-fast) ease, color var(--ui-fast) ease, box-shadow var(--ui-fast) ease, transform var(--ui-fast) ease;
    }

    .nav-links a.is-quick-tab {
      color: var(--text);
      background: rgba(127, 166, 80, 0.16);
    }

    .nav-links > a {
      min-height: 38px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      background: rgba(0, 0, 0, 0.16);
    }

    .nav-menu a {
      justify-content: flex-start;
      width: 100%;
      min-height: 38px;
      padding: 0 12px;
    }

    .nav-links a:hover,
    .nav-links a:focus-visible {
      color: var(--text);
      background: rgba(255, 255, 255, 0.08);
      transform: translateY(-1px);
      outline: none;
    }

    .nav-links a[aria-current="page"],
    .nav-links a.is-active-tab {
      color: #10150d;
      background: var(--green);
      box-shadow: 0 8px 20px rgba(127, 166, 80, 0.24);
    }

    .nav-links::-webkit-scrollbar {
      height: 6px;
    }

    .nav-links::-webkit-scrollbar-track {
      background: rgba(255, 255, 255, 0.06);
      border-radius: 999px;
    }

    .nav-links::-webkit-scrollbar-thumb {
      background: rgba(240, 217, 181, 0.42);
      border-radius: 999px;
    }

    .player-flex-chip {
      position: relative;
      isolation: isolate;
      display: grid;
      grid-template-columns: auto minmax(92px, 1fr);
      align-items: center;
      gap: 8px;
      flex: 0 0 auto;
      min-width: 222px;
      max-width: 270px;
      padding: 6px 8px 6px 6px;
      border: 1px solid rgba(231, 182, 93, 0.34);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 8% 10%, rgba(231, 182, 93, 0.2), transparent 34%),
        linear-gradient(135deg, rgba(127, 166, 80, 0.18), rgba(111, 168, 220, 0.1)),
        rgba(0, 0, 0, 0.22);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 10px 26px rgba(0, 0, 0, 0.22);
      transition: transform var(--move-speed) ease, border-color var(--move-speed) ease;
    }

    .player-flex-chip:hover,
    .player-flex-chip:focus-visible,
    .player-flex-chip.is-active-tab,
    .player-flex-chip[aria-current="page"] {
      border-color: rgba(231, 182, 93, 0.72);
      transform: translateY(-1px);
      outline: none;
    }

    .player-flex-chip .player-profile-avatar {
      width: 42px;
      height: 42px;
      min-height: 42px;
      border-radius: 10px;
      font-size: 1.28rem;
    }

    .player-flex-main {
      min-width: 0;
      display: grid;
      gap: 3px;
    }

    .player-flex-name {
      display: flex;
      align-items: center;
      gap: 6px;
      min-width: 0;
      color: var(--text);
      font-size: 0.86rem;
      font-weight: 1000;
      line-height: 1.05;
    }

    .player-flex-name [data-profile-field="name"] {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .player-flex-name [data-profile-field="name"].styled-username {
      overflow: visible;
      text-overflow: clip;
    }

    .player-flex-title {
      overflow: hidden;
      color: var(--gold);
      font-size: 0.58rem;
      font-weight: 1000;
      letter-spacing: 0.05em;
      text-overflow: ellipsis;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .player-flex-meta {
      display: flex;
      align-items: center;
      gap: 5px;
      color: var(--muted);
      font-size: 0.61rem;
      font-weight: 900;
      line-height: 1;
      white-space: nowrap;
    }

    .player-flex-chip > .player-flex-main:last-child {
      display: grid;
    }

    .player-flex-progress {
      height: 5px;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.12);
    }

    .player-flex-progress span {
      display: block;
      width: 0;
      height: 100%;
      background: linear-gradient(90deg, var(--green), var(--gold));
      transition: width 520ms cubic-bezier(0.22, 1, 0.36, 1);
    }

    .player-flex-achievements {
      display: none;
    }

    .player-flex-achievements .player-profile-achievement {
      width: 24px;
      min-height: 24px;
      border-radius: 7px;
      font-size: 0.9rem;
    }

    .site-panel,
    #shorts {
      scroll-margin-top: 88px;
    }

    body.site-tab-mode .hero {
      display: none;
    }

    body.site-tab-mode main > .site-panel:not(.is-active-panel) {
      display: none;
    }

    body:not(.site-tab-mode) main > .site-panel {
      display: none;
    }

    .site-panel[hidden] {
      display: none !important;
      contain: layout paint style;
    }

    body.site-tab-mode main > .site-panel.is-active-panel {
      min-height: calc(100svh - 68px);
      animation: sitePanelIn var(--ui-fast) ease both;
    }

    @keyframes sitePanelIn {
      from {
        opacity: 0;
        transform: translateY(10px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .hero {
      position: relative;
      display: grid;
      align-items: center;
      overflow: hidden;
      min-height: clamp(540px, 78svh, 780px);
      border-bottom: 1px solid var(--line);
      isolation: isolate;
    }

    .hero::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(90deg, rgba(32, 29, 26, 0.92) 0%, rgba(32, 29, 26, 0.78) 42%, rgba(32, 29, 26, 0.44) 100%),
        radial-gradient(circle at 68% 30%, rgba(231, 182, 93, 0.14), transparent 34%);
      z-index: -1;
      pointer-events: none;
    }

    .hero-board {
      position: absolute;
      right: max(-80px, calc((100vw - var(--max)) / 2 - 90px));
      top: 50%;
      width: min(680px, 64vw);
      aspect-ratio: 1;
      transform: translateY(-48%) rotate(2deg);
      box-shadow: var(--shadow);
      border: 10px solid #181512;
      background: #181512;
      z-index: -2;
    }

    .hero-board-grid,
    .puzzle-board {
      display: grid;
      grid-template-columns: repeat(8, minmax(0, 1fr));
      grid-template-rows: repeat(8, minmax(0, 1fr));
      gap: 0;
      align-items: stretch;
      justify-items: stretch;
    }

    .hero-square,
    .puzzle-square {
      display: grid;
      place-items: center;
      width: 100%;
      height: 100%;
      min-width: 0;
      min-height: 0;
      margin: 0;
      box-sizing: border-box;
      aspect-ratio: auto;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(1.8rem, 5vw, 4.6rem);
      user-select: none;
      line-height: 1;
      overflow: hidden;
      backface-visibility: hidden;
      -webkit-tap-highlight-color: transparent;
    }

    .light {
      background-color: var(--board-light);
      background-image: var(--board-light-texture);
    }

    .dark {
      background-color: var(--board-dark);
      background-image: var(--board-dark-texture);
    }

    .white-piece {
      color: inherit;
      filter: none;
    }

    .black-piece {
      color: inherit;
      filter: none;
    }

    .piece-symbol {
      display: inline-grid;
      place-items: center;
      width: 100%;
      height: 100%;
      color: var(--piece-white-fill, #fff8ed);
      font-family: "Noto Sans Symbols 2", "Segoe UI Symbol", "DejaVu Sans", "Arial Unicode MS", serif;
      font-size: 0.8em;
      font-weight: 500;
      line-height: 1;
      text-shadow: 0 1px 1px rgba(58, 38, 22, 0.36);
      transform: none;
