    .black-piece .piece-symbol,
    .piece-symbol.black-piece {
      color: var(--piece-black-fill, #1d1a17);
      -webkit-text-stroke: 0.004em var(--piece-black-stroke, rgba(238, 226, 205, 0.42));
      text-shadow:
        0 1px 0 rgba(255, 248, 237, 0.16),
        0 2px 2px rgba(0, 0, 0, 0.55),
        0 0 1px rgba(255, 248, 237, 0.32),
        0 0 4px var(--piece-preview-glow, rgba(231, 182, 93, 0.14));
    }

    .white-piece .piece-symbol,
    .piece-symbol.white-piece {
      color: var(--piece-white-fill, #f3ead9);
      -webkit-text-stroke: 0.005em var(--piece-white-stroke, rgba(58, 45, 34, 0.78));
      text-shadow:
        0 1px 0 rgba(255, 255, 255, 0.56),
        0 2px 2px rgba(0, 0, 0, 0.42),
        0 0 1px rgba(58, 45, 34, 0.62),
        0 0 4px var(--piece-preview-glow, rgba(231, 182, 93, 0.16));
    }

    .piece-symbol {
      font-family: "Noto Sans Symbols 2", "Segoe UI Symbol", "DejaVu Sans", "Arial Unicode MS", serif;
      font-size: clamp(1.95rem, 7.25vmin, 4.05rem);
      font-weight: 500;
      line-height: 1;
      display: grid;
      place-items: center;
      position: relative;
      width: 100%;
      height: 100%;
      transform: translateY(-0.015em) scaleX(0.96);
      filter: saturate(1.02) contrast(1.03);
      -webkit-font-smoothing: antialiased;
      text-rendering: geometricPrecision;
      transition: transform var(--move-speed) cubic-bezier(.2, .85, .25, 1), filter var(--move-speed) ease;
    }

    .piece-symbol.white-piece[data-material],
    .piece-symbol.black-piece[data-material] {
      color: transparent;
      -webkit-text-fill-color: transparent;
      background-image: var(--piece-material-fill);
      -webkit-background-clip: text;
      background-clip: text;
    }

    .piece-symbol.white-piece[data-material] {
      --finish-light: #fffdf7;
      --finish-mid: var(--piece-white-fill, #f8f6f0);
      --finish-deep: color-mix(in srgb, var(--piece-white-fill, #f8f6f0) 72%, #92795e);
    }

    .piece-symbol.black-piece[data-material] {
      --finish-light: color-mix(in srgb, var(--piece-black-fill, #1d1814) 68%, #a9b0b8);
      --finish-mid: var(--piece-black-fill, #1d1814);
      --finish-deep: color-mix(in srgb, var(--piece-black-fill, #1d1814) 78%, #030405);
    }

    .piece-symbol[data-material="matte"] { --piece-material-fill: linear-gradient(160deg, var(--finish-light), var(--finish-mid) 48%, var(--finish-deep)); }
    .piece-symbol[data-material="glossy"] { --piece-material-fill: linear-gradient(145deg, var(--finish-light) 0 19%, var(--finish-mid) 31% 56%, var(--finish-light) 66%, var(--finish-deep) 100%); }
    .piece-symbol[data-material="metallic"] { --piece-material-fill: linear-gradient(100deg, var(--finish-deep), var(--finish-light) 23%, var(--finish-mid) 43%, var(--finish-light) 61%, var(--finish-deep)); }
    .piece-symbol[data-material="marble"] { --piece-material-fill: repeating-linear-gradient(112deg, var(--finish-light) 0 10%, var(--finish-mid) 10% 25%, var(--finish-deep) 25% 28%, var(--finish-mid) 28% 46%); }
    .piece-symbol[data-material="crystal"] { --piece-material-fill: linear-gradient(135deg, var(--finish-light) 0 28%, var(--finish-mid) 28% 58%, var(--finish-light) 58% 65%, var(--finish-deep) 65%); }
    .piece-symbol[data-material="obsidian"] { --piece-material-fill: linear-gradient(150deg, var(--finish-light), var(--finish-mid) 35%, var(--finish-deep) 72%, #020303); }
    .piece-symbol[data-material="wooden"] { --piece-material-fill: repeating-linear-gradient(102deg, var(--finish-light) 0 8%, var(--finish-mid) 8% 21%, var(--finish-deep) 21% 25%, var(--finish-mid) 25% 39%); }

    .piece-symbol[data-material="glossy"],
    .piece-symbol[data-material="metallic"],
    .piece-symbol[data-material="crystal"] {
      filter: saturate(1.08) contrast(1.05) drop-shadow(0 2px 2px rgba(0, 0, 0, 0.26));
    }

    .piece-symbol[data-rarity="Legendary"],
    .piece-symbol[data-rarity="Mythic"],
    .piece-symbol[data-rarity="Divine"] {
      text-shadow:
        0 1px 0 rgba(255, 255, 255, 0.42),
        0 2px 3px rgba(0, 0, 0, 0.42),
        0 0 4px var(--piece-preview-glow, rgba(231, 182, 93, 0.28)),
        0 0 12px var(--piece-preview-glow, rgba(231, 182, 93, 0.18));
    }

    .piece-symbol[data-rarity="Legendary"] {
      filter: saturate(1.1) contrast(1.08) drop-shadow(0 0 4px var(--piece-preview-glow, rgba(231, 182, 93, 0.2)));
    }

    .piece-symbol[data-rarity="Mythic"],
    .piece-symbol[data-rarity="Divine"] {
      filter: saturate(1.14) contrast(1.1) drop-shadow(0 0 6px var(--piece-preview-glow, rgba(151, 115, 255, 0.24)));
    }

    .piece-symbol[data-rarity="Legendary"]::after,
    .piece-symbol[data-rarity="Mythic"]::after,
    .piece-symbol[data-rarity="Divine"]::after {
      content: attr(data-symbol);
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      color: transparent;
      -webkit-text-stroke: 0;
      background: linear-gradient(115deg, transparent 18%, rgba(255,255,255,.72) 45%, transparent 72%);
      background-size: 230% 100%;
      -webkit-background-clip: text;
      background-clip: text;
      opacity: 0.55;
      pointer-events: none;
      animation: piecePremiumShine 3.8s ease-in-out infinite;
    }

    .piece-symbol[data-rarity="Mythic"]::after,
    .piece-symbol[data-rarity="Divine"]::after {
      opacity: 0.72;
      animation-duration: 3.1s;
    }

    @keyframes piecePremiumShine {
      0%, 18% { background-position: 140% 0; opacity: 0; }
      42% { opacity: 0.68; }
      72%, 100% { background-position: -120% 0; opacity: 0; }
    }

    .piece-svg {
      width: 88%;
      height: 88%;
      max-width: 5.05rem;
      max-height: 5.05rem;
      display: block;
      margin: auto;
      pointer-events: none;
      object-fit: contain;
      object-position: center;
      user-select: none;
      overflow: visible;
      filter: var(--piece-svg-filter, none);
      transform: translate3d(0, 0, 0);
      backface-visibility: hidden;
      contain: paint;
    }

    body.piece-finish-crystal {
      --piece-svg-filter: saturate(1.08) contrast(1.04) drop-shadow(0 1px 1px rgba(4, 43, 70, 0.34)) drop-shadow(0 0 5px rgba(126, 228, 255, 0.24));
    }

    body.piece-finish-marble {
      --piece-svg-filter: grayscale(0.32) saturate(0.54) contrast(1.08) drop-shadow(0 1px 1px rgba(46, 48, 50, 0.3));
    }

    body.piece-finish-obsidian {
      --piece-svg-filter: grayscale(0.5) saturate(0.7) contrast(1.18) drop-shadow(0 2px 2px rgba(0, 0, 0, 0.52));
    }

    .mini-square .piece-svg {
