    .player-avatar-strip {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding: 6px 2px 10px;
      scroll-snap-type: x proximity;
    }

    .avatar-choice {
      min-width: 92px;
      min-height: 72px;
      display: grid;
      grid-template-rows: 30px auto;
      place-items: center;
      gap: 5px;
      padding: 9px 8px;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 12px;
      background:
        linear-gradient(135deg, rgba(255, 248, 237, 0.08), rgba(127, 166, 80, 0.08)),
        rgba(0, 0, 0, 0.16);
      color: var(--text);
      font: inherit;
      font-weight: 900;
      cursor: pointer;
      scroll-snap-align: start;
      transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
