    .account-vault[open] summary span {
      color: var(--muted);
    }

    .account-vault h3,
    .account-vault p {
      margin: 0;
    }

    .account-vault-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
    }

    .account-vault-grid span {
      min-height: 54px;
      padding: 9px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 8px;
      background: rgba(255, 248, 237, 0.04);
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 850;
      line-height: 1.3;
    }

    .account-vault-grid strong {
      display: block;
      color: var(--soft);
      font-size: 0.95rem;
    }

    @media (max-width: 620px) {
