        grid-template-columns: 1fr;
      }
    }

    .login-player-profile {
      margin-top: 2px;
      color: var(--text);
      padding: 0;
      border: 0;
      background: transparent;
      box-shadow: none;
    }

    .login-player-profile::before {
      content: "Adventure card";
      display: inline-flex;
      width: max-content;
      margin-bottom: 8px;
      padding: 5px 9px;
      border: 1px solid rgba(231, 182, 93, 0.28);
      border-radius: 999px;
      background: rgba(231, 182, 93, 0.12);
      color: var(--gold);
      font-size: 0.72rem;
      font-weight: 1000;
      text-transform: uppercase;
    }

    .home-stat-grid,
    .quick-practice,
    .recommendation-list {
      display: grid;
      gap: 8px;
    }

    .home-stat-grid,
    .quick-practice {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .recommendation-list {
      grid-template-columns: 1fr;
    }

    .home-stat {
      display: grid;
      align-content: center;
      gap: 3px;
      min-height: 58px;
      padding: 10px 12px;
      border: 1px solid rgba(231, 182, 93, 0.14);
      border-radius: 7px;
      background: rgba(231, 182, 93, 0.12);
      color: var(--gold);
      font-size: 0.84rem;
      font-weight: 900;
      line-height: 1.2;
    }

    .home-stat strong {
      color: var(--text);
      font-size: 1rem;
      line-height: 1.1;
    }

    .home-stat small {
      color: var(--muted);
      font-size: 0.66rem;
      font-weight: 900;
      text-transform: uppercase;
    }

    .home-stat.is-highlight {
      border-color: rgba(127, 166, 80, 0.34);
      background: rgba(127, 166, 80, 0.16);
    }

    .trust-strip,
    .next-step-card {
      display: grid;
      gap: 8px;
      margin-top: 14px;
    }

    .trust-strip {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .trust-strip span,
    .next-step-card {
      border: 1px solid rgba(231, 182, 93, 0.24);
      border-radius: 7px;
      background: rgba(231, 182, 93, 0.11);
      color: var(--soft);
    }

    .trust-strip span {
      display: grid;
      place-items: center;
      min-height: 38px;
      padding: 6px 8px;
      font-size: 0.78rem;
      font-weight: 900;
      text-align: center;
    }

    .next-step-card {
      margin-top: 0;
      padding: 14px;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
    }

    .next-step-card strong {
      color: var(--gold);
      font-size: 0.88rem;
      text-transform: uppercase;
    }

    .next-step-card span {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .next-step-card .button {
      justify-self: start;
      min-height: 38px;
      padding: 0 14px;
    }

    .quick-practice .button {
      justify-content: flex-start;
      min-height: 50px;
      padding: 0 14px;
      text-align: left;
    }

    .recommendation-list a {
      border-color: rgba(127, 166, 80, 0.38);
      background: rgba(127, 166, 80, 0.14);
    }

    .daily-goals-card {
      display: grid;
      gap: 10px;
      padding: 14px;
      border: 1px solid rgba(127, 166, 80, 0.36);
      border-radius: 10px;
      background:
        radial-gradient(circle at 92% 8%, rgba(127, 166, 80, 0.2), transparent 34%),
        rgba(127, 166, 80, 0.1);
    }

    .daily-goals-head,
    .daily-goals-reward {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
    }

    .daily-goals-head strong {
      color: var(--text);
      font-size: 0.98rem;
    }

    .daily-goals-list {
      display: grid;
      gap: 7px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .daily-goals-list a {
      display: grid;
      grid-template-columns: 24px minmax(0, 1fr) auto;
      align-items: center;
      gap: 8px;
      min-height: 38px;
      padding: 8px 10px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 8px;
      background: rgba(0, 0, 0, 0.12);
      color: var(--soft);
      text-decoration: none;
      font-size: 0.86rem;
      font-weight: 900;
    }

    .daily-goals-list a.is-done {
      border-color: rgba(127, 166, 80, 0.48);
      background: rgba(127, 166, 80, 0.18);
      color: var(--text);
    }

    .daily-goals-check {
      display: grid;
      place-items: center;
      width: 22px;
      height: 22px;
      border: 1px solid rgba(255, 248, 237, 0.26);
      border-radius: 6px;
      color: var(--gold);
      font-size: 0.86rem;
      line-height: 1;
    }

    .daily-goals-progress {
      color: var(--muted);
      font-size: 0.72rem;
      white-space: nowrap;
    }

    .daily-goals-reward span {
      color: var(--gold);
      font-size: 0.86rem;
      font-weight: 1000;
    }

    .daily-goals-reward .button {
      min-height: 36px;
      padding: 0 12px;
    }

    .achievement-roadmap {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 6px;
      padding: 9px;
      border: 1px solid rgba(231, 182, 93, 0.18);
      border-radius: 10px;
      background: rgba(0, 0, 0, 0.12);
    }

    .roadmap-step {
      position: relative;
      display: grid;
      gap: 4px;
      min-height: 66px;
      padding: 8px 7px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 8px;
      background: rgba(255, 255, 255, 0.045);
      color: var(--muted);
      text-align: center;
      font-size: 0.68rem;
      font-weight: 950;
    }

    .roadmap-step::after {
      content: "";
      position: absolute;
      top: 17px;
      right: -9px;
      width: 12px;
      height: 2px;
      border-radius: 99px;
      background: rgba(231, 182, 93, 0.28);
    }

    .roadmap-step:last-child::after {
      display: none;
    }

    .roadmap-step strong {
      color: var(--text);
      font-size: 0.72rem;
      line-height: 1.1;
    }

    .roadmap-step span {
      display: grid;
      place-items: center;
      width: 26px;
      height: 26px;
      margin-inline: auto;
      border-radius: 999px;
      background: rgba(255, 248, 237, 0.1);
      color: var(--gold);
    }

    .roadmap-step.is-unlocked {
      border-color: rgba(127, 166, 80, 0.46);
      background: linear-gradient(135deg, rgba(127, 166, 80, 0.18), rgba(231, 182, 93, 0.1));
      color: var(--soft);
    }

    .roadmap-step.is-current {
      border-color: rgba(231, 182, 93, 0.65);
      box-shadow: 0 0 20px rgba(231, 182, 93, 0.16);
    }

    @media (max-width: 640px) {
      .achievement-roadmap {
        grid-template-columns: repeat(5, minmax(82px, 1fr));
        overflow-x: auto;
        scrollbar-width: none;
      }
    }

    .login-shell {
      display: grid;
      grid-template-columns: minmax(290px, 0.78fr) minmax(420px, 1.22fr);
      gap: 22px;
      align-items: stretch;
    }

    .login-card,
    .login-pass {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.07);
      box-shadow: var(--shadow);
    }

    .login-card {
      display: grid;
      gap: 16px;
      padding: 24px;
      position: relative;
      overflow: hidden;
      align-content: start;
      background:
        radial-gradient(circle at 92% 10%, rgba(231, 182, 93, 0.16), transparent 28%),
        linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(127, 166, 80, 0.08));
    }

    .login-card p,
    .login-pass p {
      margin: 0;
      color: var(--muted);
    }

    .login-card h3 {
      margin: 0;
      font-size: clamp(1.45rem, 3vw, 2.2rem);
      line-height: 1.05;
    }

    .login-perks {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 10px;
    }

    .login-perks span,
    .login-avatar {
      display: grid;
      place-items: center;
      min-height: 54px;
      border-radius: 7px;
      background: rgba(231, 182, 93, 0.16);
      color: var(--gold);
      font-weight: 1000;
      text-align: center;
    }

    .login-perks span {
      place-items: start;
      align-content: start;
      min-height: 96px;
      padding: 12px;
      text-align: left;
    }

    .login-perks strong,
    .login-perks small {
      display: block;
    }

    .login-perks strong {
      color: var(--soft);
      line-height: 1.15;
    }

    .login-perks small {
      margin-top: 7px;
      color: var(--muted);
      font-size: 0.78rem;
      line-height: 1.35;
    }

    .login-quest-list {
      display: grid;
      gap: 9px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .login-quest-list li {
      display: grid;
      grid-template-columns: 26px 1fr;
      gap: 10px;
      align-items: center;
      min-height: 42px;
      padding: 8px 10px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.055);
      color: var(--muted);
      font-weight: 800;
      line-height: 1.35;
    }

    .login-quest-list b {
      display: grid;
      place-items: center;
      width: 26px;
      height: 26px;
      border-radius: 6px;
      background: rgba(127, 166, 80, 0.2);
      color: var(--gold);
    }

    .login-progress-preview {
      display: grid;
      gap: 8px;
      padding: 12px;
      border: 1px solid rgba(127, 166, 80, 0.26);
      border-radius: 7px;
      background: rgba(127, 166, 80, 0.1);
    }

    .login-progress-preview span {
      color: var(--gold);
      font-size: 0.8rem;
      font-weight: 1000;
      text-transform: uppercase;
    }

    .login-progress-preview div {
      height: 9px;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.12);
    }

    .login-progress-preview i {
      display: block;
      width: 34%;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--green), var(--gold));
    }

    .login-card-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 2px;
    }

    .login-pass {
      position: relative;
      display: grid;
      gap: 14px;
      padding: 18px;
      overflow: hidden;
      background:
        radial-gradient(circle at 82% 0%, rgba(231, 182, 93, 0.2), transparent 34%),
        linear-gradient(135deg, rgba(127, 166, 80, 0.22), rgba(111, 168, 220, 0.12)),
        rgba(255, 255, 255, 0.07);
    }

    .login-pass::before {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background:
        linear-gradient(115deg, transparent 0 38%, rgba(255, 248, 237, 0.06) 45%, transparent 54%),
        radial-gradient(circle at 8% 92%, rgba(127, 166, 80, 0.16), transparent 28%);
    }

    .login-pass > * {
      position: relative;
      z-index: 1;
    }

    .login-pass-grid {
      display: grid;
      grid-template-columns: minmax(330px, 1.08fr) minmax(280px, 0.92fr);
      gap: 14px;
      align-items: start;
    }

    .login-pass-panel {
      display: grid;
      gap: 12px;
      padding: 14px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 100% 0%, rgba(231, 182, 93, 0.12), transparent 32%),
        rgba(0, 0, 0, 0.13);
    }

    .login-pass-panel h4 {
      margin: 0;
      color: var(--soft);
      font-size: 1rem;
    }

    .login-avatar {
      width: 86px;
      height: 86px;
      min-height: 86px;
      border: 2px solid rgba(231, 182, 93, 0.5);
      border-radius: 20px;
      background:
        radial-gradient(circle at 72% 20%, rgba(231, 182, 93, 0.95) 0 12%, transparent 13%),
        linear-gradient(145deg, rgba(127, 166, 80, 0.94), rgba(21, 96, 79, 0.94));
      color: #fff8eb;
      box-shadow: inset 0 -14px 28px rgba(0, 0, 0, 0.24), 0 14px 34px rgba(0, 0, 0, 0.22);
      font-size: 2.75rem;
    }

    .login-form {
      display: grid;
      gap: 12px;
      padding: 14px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.045);
    }

    .login-form label {
      display: grid;
      gap: 6px;
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 800;
    }

    .login-form input,
    .login-form select {
      min-height: 44px;
      width: 100%;
      border: 1px solid var(--line);
      border-radius: 7px;
      background: rgba(0, 0, 0, 0.18);
      color: var(--text);
      padding: 0 12px;
      font: inherit;
    }

    .login-form input:focus,
    .login-form select:focus {
      border-color: rgba(231, 182, 93, 0.55);
      outline: none;
      box-shadow: 0 0 0 3px rgba(231, 182, 93, 0.12);
    }

    .login-actions {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .auth-panel {
      display: grid;
      gap: 14px;
      padding: 14px;
      border: 1px solid rgba(231, 182, 93, 0.22);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 96% 0%, rgba(231, 182, 93, 0.14), transparent 34%),
        rgba(0, 0, 0, 0.16);
    }

    .auth-panel h3,
    .auth-panel p {
      margin: 0;
    }

    .auth-session-loading,
    .auth-account-panel {
      display: flex;
      align-items: center;
      gap: 10px;
      min-height: 58px;
      padding: 11px;
      border: 1px solid rgba(126, 179, 87, 0.32);
      border-radius: 9px;
      background: rgba(126, 179, 87, 0.1);
    }

    .auth-session-loading[hidden],
    .auth-account-panel[hidden] {
      display: none;
    }

    .auth-session-loading::before {
      content: "";
      width: 42px;
      height: 36px;
      border-radius: 7px;
      background: linear-gradient(105deg, rgba(255, 248, 237, 0.08) 22%, rgba(255, 248, 237, 0.3) 48%, rgba(255, 248, 237, 0.08) 74%);
      background-size: 230% 100%;
      animation: uiSkeletonShimmer 1.15s ease-in-out infinite;
    }

    .auth-session-loading::after,
    .status-skeleton::after,
    .coach-skeleton::after {
      content: "";
      display: block;
      width: min(18rem, 68%);
      height: 0.75rem;
      border-radius: 999px;
      background: linear-gradient(105deg, rgba(255, 248, 237, 0.08) 22%, rgba(255, 248, 237, 0.3) 48%, rgba(255, 248, 237, 0.08) 74%);
      background-size: 230% 100%;
      animation: uiSkeletonShimmer 1.15s ease-in-out infinite;
    }

    .status-skeleton,
    .coach-skeleton {
      color: transparent !important;
      overflow: hidden;
    }

    .status-skeleton::after {
      width: 5.5rem;
      height: 0.7rem;
    }

    .coach-skeleton::after {
      width: min(24rem, 78%);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @keyframes uiSkeletonShimmer {
      from { background-position: 180% 0; }
      to { background-position: -80% 0; }
    }

    .auth-account-avatar {
      display: grid;
      place-items: center;
      flex: 0 0 42px;
      width: 42px;
      height: 42px;
      overflow: hidden;
      border: 1px solid rgba(231, 182, 93, 0.55);
      border-radius: 8px;
      background: rgba(0, 0, 0, 0.2);
      font-size: 1.35rem;
    }

    .auth-account-copy {
      display: grid;
      gap: 3px;
      min-width: 0;
      flex: 1;
    }

    .auth-account-copy strong,
    .auth-account-copy small {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .auth-account-copy small {
      color: var(--muted);
      font-weight: 800;
    }

    .auth-account-panel .button {
      flex: 0 0 auto;
    }

    .auth-account-actions {
      display: flex;
      flex: 0 0 auto;
      gap: 7px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    @media (max-width: 520px) {
      .auth-account-panel { align-items: flex-start; flex-wrap: wrap; }
      .auth-account-actions { width: 100%; }
      .auth-account-actions .button { flex: 1 1 140px; }
    }

    @keyframes auth-spin {
      to { transform: rotate(360deg); }
    }

    .auth-tabs {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
      padding: 5px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 8px;
      background: rgba(0, 0, 0, 0.14);
    }

    .auth-tab {
      min-height: 38px;
      border: 0;
      border-radius: 7px;
      background: transparent;
      color: var(--muted);
      font: inherit;
      font-weight: 950;
      cursor: pointer;
    }

    .auth-tab[aria-selected="true"] {
      background: var(--green);
      color: #10150d;
    }

    .auth-form {
      display: grid;
      gap: 10px;
    }

    .auth-form[hidden] {
      display: none;
    }

    .auth-field {
      display: grid;
      gap: 5px;
    }

    .auth-field small,
    .auth-status,
    .auth-note {
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 800;
      line-height: 1.35;
    }

    .auth-field small.is-error,
    .auth-status.is-error {
      color: #ffb8ad;
    }

    .auth-status.is-success {
      color: #bce38c;
    }

    .auth-note {
      padding: 10px;
      border: 1px solid rgba(111, 168, 220, 0.18);
      border-radius: 7px;
      background: rgba(111, 168, 220, 0.09);
    }

    .auth-security {
      display: grid;
      gap: 7px;
      margin: 0;
      padding: 10px 12px;
      border: 1px solid rgba(126, 179, 87, 0.2);
      border-radius: 8px;
      background: rgba(126, 179, 87, 0.08);
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 850;
      list-style: none;
    }

    .auth-security li::before {
      content: "\2713";
      margin-right: 8px;
      color: var(--gold);
    }

    .auth-tools {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
      justify-content: space-between;
    }

    .auth-check {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--muted);
      font-size: 0.84rem;
      font-weight: 850;
    }

    .auth-check input {
      width: 18px;
      height: 18px;
      accent-color: var(--green);
    }

    .auth-mini-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }

    .auth-mini-actions .button {
      min-height: 36px;
      padding: 0 12px;
      font-size: 0.82rem;
    }

    .metric {
      min-height: 88px;
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(47, 43, 39, 0.76);
    }

    .metric strong {
      display: block;
      color: var(--soft);
      font-size: 1.55rem;
      line-height: 1;
    }

    .metric span {
      display: block;
      margin-top: 8px;
      color: var(--muted);
      font-size: 0.9rem;
    }

    section {
      padding: 76px 0;
    }

    .section-dark {
      background:
        radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--gold) 10%, transparent), transparent 30%),
        linear-gradient(180deg, color-mix(in srgb, var(--bg) 64%, transparent), color-mix(in srgb, var(--bg) 48%, transparent));
      backdrop-filter: blur(2px);
    }

    body.theme-light .site-header {
      background: rgba(246, 241, 232, 0.94);
    }

    body.theme-light .nav-links,
