      align-items: end;
      justify-content: space-between;
      gap: 28px;
      margin-bottom: 28px;
    }

    .section-kicker {
      margin: 0 0 8px;
      color: var(--gold);
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h2 {
      margin-bottom: 0;
      font-size: clamp(2rem, 4.2vw, 3.4rem);
      line-height: 1;
      letter-spacing: 0;
    }

    .section-intro {
      max-width: 54ch;
      margin-bottom: 0;
      color: var(--muted);
    }

    .path-tabs {
      display: inline-grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 4px;
      padding: 4px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(0, 0, 0, 0.18);
    }

    .tab-button {
      min-height: 38px;
      padding: 0 14px;
      border: 0;
      border-radius: 6px;
      background: transparent;
      color: var(--muted);
      font: inherit;
      font-size: 0.92rem;
      font-weight: 800;
      cursor: pointer;
      white-space: nowrap;
    }

    .tab-button[aria-selected="true"] {
      background: var(--green);
      color: #11170e;
    }

    .lesson-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 16px;
    }

    .lesson-card,
    .adventure-card,
    .mission-card,
    .adventure-play,
    .rule-item,
    .opening-card,
    .notation-card,
    .book-card,
    .book-detail,
    .video-card,
    .puzzle-shell {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background:
        linear-gradient(145deg, rgba(255,255,255,.055), rgba(255,255,255,.018)),
        color-mix(in srgb, var(--panel) 74%, transparent);
      box-shadow: 0 16px 35px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255,255,255,.06);
      backdrop-filter: blur(10px);
    }

    .lesson-card {
      display: flex;
      flex-direction: column;
      min-height: 270px;
      padding: 20px;
    }

    .lesson-flow {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(135px, 1fr));
      gap: 10px;
      margin: 0 0 18px;
      padding: 14px;
      border: 1px solid rgba(231, 182, 93, 0.24);
      border-radius: var(--radius);
      background: rgba(231, 182, 93, 0.08);
    }

    .lesson-flow-step {
      display: grid;
      gap: 4px;
      min-height: 72px;
      padding: 11px;
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.07);
      color: var(--muted);
      font-size: 0.85rem;
      font-weight: 800;
    }

    .lesson-flow-step strong {
      color: var(--soft);
      font-size: 0.98rem;
    }

    .lesson-journey {
      display: grid;
      gap: 12px;
      margin: 0 0 18px;
      padding: 16px;
      border: 1px solid rgba(127, 166, 80, 0.28);
      border-radius: var(--radius);
      background: rgba(127, 166, 80, 0.08);
    }

    .lesson-journey h3 {
      margin: 0;
      font-size: 1.16rem;
    }

    .journey-steps {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 8px;
    }

    .journey-step {
      min-height: 42px;
      padding: 0 12px;
      border: 1px solid rgba(239, 229, 211, 0.14);
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.06);
      color: var(--soft);
      font: inherit;
      font-weight: 900;
      text-align: left;
      cursor: pointer;
    }

    .journey-step.is-complete {
      border-color: rgba(127, 166, 80, 0.5);
      background: rgba(127, 166, 80, 0.18);
    }

    .journey-step.is-current {
      border-color: rgba(231, 182, 93, 0.55);
      background: rgba(231, 182, 93, 0.14);
    }

    .journey-step.is-locked {
      color: var(--muted);
      cursor: not-allowed;
      opacity: 0.72;
    }

    .lesson-card.is-locked .topic-list,
    .lesson-card.is-locked .lesson-mission-note,
    .lesson-card.is-locked .lesson-card-footer {
      display: none;
    }

    .lesson-card.is-locked > p:not(.lesson-lock-note) {
      color: var(--muted);
      opacity: 0.78;
    }

    .lesson-lock-note {
      display: none;
      margin-top: auto;
      padding: 10px 12px;
      border: 1px solid rgba(231, 182, 93, 0.18);
      border-radius: 7px;
      background: rgba(231, 182, 93, 0.08);
      color: var(--muted);
      font-weight: 800;
    }

    .lesson-card.is-locked .lesson-lock-note {
      display: block;
    }

    .lesson-mission-note {
      margin: 12px 0 0;
      padding: 10px 12px;
      border: 1px solid rgba(127, 166, 80, 0.28);
      border-radius: 7px;
      background: rgba(127, 166, 80, 0.1);
      color: var(--soft);
      font-size: 0.86rem;
      font-weight: 850;
    }

    .lesson-card-footer {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
      margin-top: auto;
      padding-top: 16px;
    }

    .lesson-card-footer .button {
      width: 100%;
      min-height: 44px;
      padding-inline: 10px;
      text-align: center;
    }

    .lesson-time {
      grid-column: 1 / -1;
      color: var(--gold);
      font-size: 0.82rem;
      font-weight: 900;
    }

    .gentle-start {
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(320px, 1.25fr);
      gap: 20px;
      margin: 0 0 26px;
      padding: 22px;
      border: 1px solid rgba(231, 182, 93, 0.24);
      border-radius: var(--radius);
      background:
        linear-gradient(135deg, rgba(127, 166, 80, 0.16), rgba(111, 168, 220, 0.09)),
        var(--panel);
      box-shadow: 0 20px 46px rgba(0, 0, 0, 0.18);
    }

    .gentle-copy h3,
    .gentle-output h4 {
      margin-bottom: 10px;
      font-size: 1.34rem;
      line-height: 1.18;
    }

    .gentle-copy p,
    .gentle-output p {
      color: var(--muted);
    }

    .gentle-badges,
    .gentle-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 16px;
    }

    .gentle-badge {
      display: inline-flex;
      align-items: center;
      min-height: 30px;
      padding: 0 10px;
      border: 1px solid rgba(255, 248, 237, 0.13);
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.07);
      color: var(--soft);
      font-size: 0.82rem;
      font-weight: 900;
    }

    .gentle-checklist {
      display: grid;
      gap: 9px;
      margin: 16px 0 18px;
      padding: 0;
      list-style: none;
    }

    .gentle-checklist li {
      display: grid;
      grid-template-columns: 30px 1fr;
      gap: 10px;
      align-items: center;
      color: var(--muted);
      font-weight: 800;
    }

    .gentle-checklist span {
      display: grid;
      place-items: center;
      width: 30px;
      height: 30px;
      border-radius: 7px;
      background: rgba(231, 182, 93, 0.15);
      color: var(--gold);
      font-weight: 900;
    }

    .gentle-coach {
      display: grid;
      gap: 14px;
      padding: 16px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: var(--radius);
      background: rgba(0, 0, 0, 0.16);
    }

    .gentle-form {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
      gap: 10px;
      align-items: end;
    }

    .gentle-form label {
      display: grid;
      gap: 7px;
      color: var(--muted);
      font-size: 0.86rem;
      font-weight: 900;
    }

    .gentle-form select {
      min-height: 42px;
      padding: 0 11px;
      border: 1px solid rgba(255, 248, 237, 0.15);
      border-radius: 7px;
      background: #211d1a;
      color: var(--text);
      font: inherit;
      font-weight: 800;
    }

    .gentle-output {
      display: grid;
      gap: 12px;
      min-height: 220px;
      padding: 16px;
      border: 1px solid rgba(127, 166, 80, 0.2);
      border-radius: var(--radius);
      background: rgba(127, 166, 80, 0.08);
    }

    .gentle-task-list {
      display: grid;
      gap: 9px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .gentle-task {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) auto auto;
      gap: 10px;
      align-items: center;
      min-height: 58px;
      padding: 10px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.05);
    }

    .gentle-task input {
      width: 19px;
      height: 19px;
      accent-color: var(--green);
    }

    .gentle-task.is-done {
      border-color: rgba(127, 166, 80, 0.34);
      background: rgba(127, 166, 80, 0.12);
    }

    .gentle-task strong,
    .gentle-task small {
      display: block;
    }

    .gentle-task small {
      margin-top: 3px;
      color: var(--muted);
      line-height: 1.42;
    }

    .gentle-time {
      color: var(--gold);
      font-size: 0.82rem;
      font-weight: 900;
      white-space: nowrap;
    }

    .lesson-number {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      margin-bottom: 20px;
      border-radius: 50%;
      background: var(--green);
      color: #10150d;
      font-weight: 900;
    }

    .lesson-card h3,
    .video-card h3,
    .puzzle-info h3 {
      margin-bottom: 10px;
      font-size: 1.18rem;
      line-height: 1.2;
    }

    .lesson-card p,
    .rule-item p,
    .video-card p,
    .puzzle-info p {
      color: var(--muted);
    }

    .section-warm .lesson-card p,
    .section-warm .adventure-card p,
    .section-warm .mission-card p,
    .section-warm .adventure-play p,
    .section-warm .rule-item p,
    .section-warm .opening-card p,
    .section-warm .notation-card p,
    .section-warm .book-card p,
    .section-warm .book-detail p,
    .section-warm .video-card p,
    .section-warm .puzzle-info p {
      color: #5d5144;
    }

    .topic-list {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin: 18px 0 0;
      padding: 0;
      list-style: none;
    }

    .topic-list li {
      padding: 5px 9px;
      border: 1px solid var(--line);
      border-radius: 999px;
      color: var(--muted);
      font-size: 0.82rem;
    }

    .section-warm .topic-list li {
      border-color: rgba(33, 26, 18, 0.16);
      color: #5d5144;
      background: rgba(181, 136, 99, 0.12);
    }

    .story-mode-card {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(260px, 0.8fr);
      gap: 18px;
      align-items: start;
      margin-bottom: 18px;
      padding: 20px;
      border: 1px solid rgba(33, 26, 18, 0.16);
      border-radius: var(--radius);
      background: linear-gradient(135deg, rgba(127, 166, 80, 0.16), rgba(231, 182, 93, 0.18));
      box-shadow: 0 18px 38px rgba(82, 55, 25, 0.12);
    }

    .story-mode-card h3,
    .story-mode-card p {
      margin-bottom: 8px;
    }

    .story-detail {
      display: grid;
      gap: 8px;
      margin-top: 12px;
      padding: 12px;
      border: 1px solid rgba(33, 26, 18, 0.12);
      border-radius: 7px;
      background: rgba(255, 248, 235, 0.62);
    }

    .story-detail strong,
    .story-detail span {
      display: block;
    }

    .story-detail small {
      color: #5d5144;
      line-height: 1.42;
    }

    .story-map {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 9px;
    }

    .story-node {
      min-height: 66px;
      padding: 9px;
      border: 1px solid rgba(33, 26, 18, 0.15);
      border-radius: 7px;
      background: rgba(255, 248, 235, 0.76);
      color: #2c261f;
      font: inherit;
      font-weight: 900;
      cursor: pointer;
      transition: transform 160ms ease, background 160ms ease;
    }

    .story-node span {
      display: block;
      margin-top: 4px;
      color: inherit;
      font-size: 0.76rem;
      opacity: 0.78;
    }

    .story-node:hover,
    .story-node:focus-visible,
    .story-node.is-current {
      transform: translateY(-2px);
      background: #dfeecf;
      outline: none;
    }

    .story-node.is-complete {
      background: var(--green);
      color: #10150d;
    }

    .boss-battle-panel {
      display: grid;
      gap: 16px;
      margin: 18px 0;
      padding: 20px;
      border: 1px solid rgba(231, 182, 93, 0.32);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 92% 12%, rgba(216, 111, 98, 0.18), transparent 26%),
        linear-gradient(135deg, rgba(127, 166, 80, 0.14), rgba(231, 182, 93, 0.12)),
        var(--panel);
    }

    .boss-battle-head {
      display: flex;
      justify-content: space-between;
      gap: 14px;
      align-items: end;
    }

    .boss-battle-head h3,
    .boss-battle-head p {
      margin: 0;
    }

    .boss-battle-status {
      max-width: 360px;
      color: var(--gold);
      font-weight: 900;
    }

    .boss-world-tabs {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 8px;
    }

    .boss-world-tab {
      display: grid;
      gap: 4px;
      min-height: 58px;
      padding: 9px 8px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255, 248, 237, 0.08);
      color: var(--text);
      font: inherit;
      font-weight: 900;
      cursor: pointer;
    }

    .boss-world-tab span {
      color: var(--muted);
      font-size: 0.72rem;
    }

    .boss-world-tab[aria-pressed="true"] {
      border-color: rgba(231, 182, 93, 0.78);
      background: rgba(231, 182, 93, 0.18);
    }

    .boss-world-tab:disabled {
      cursor: not-allowed;
      filter: grayscale(1);
      opacity: 0.48;
    }

    .boss-battle-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
    }

    .boss-card {
      display: grid;
      gap: 10px;
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255, 248, 237, 0.08);
      transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
    }

    .boss-card:hover {
      transform: translateY(-2px);
      border-color: rgba(231, 182, 93, 0.6);
      box-shadow: 0 14px 32px rgba(0, 0, 0, 0.18);
    }

    .boss-card.is-active {
      border-color: rgba(231, 182, 93, 0.76);
      box-shadow: 0 0 0 3px rgba(231, 182, 93, 0.12);
    }

    .boss-card.is-cleared {
      border-color: rgba(127, 166, 80, 0.72);
      background: rgba(127, 166, 80, 0.14);
    }

    .boss-card.is-boss {
      background:
        radial-gradient(circle at 88% 10%, rgba(231, 182, 93, 0.2), transparent 28%),
        rgba(255, 248, 237, 0.08);
    }

    .boss-card.is-final {
      border-color: rgba(255, 211, 107, 0.76);
      box-shadow: 0 0 0 2px rgba(255, 211, 107, 0.12), 0 18px 42px rgba(0, 0, 0, 0.2);
    }

    .boss-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
    }

    .boss-card h4,
    .boss-card p {
      margin: 0;
    }

    .boss-card h4 {
      font-size: 1.05rem;
    }

    .boss-rewards {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
    }

    .adventure-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
      margin-bottom: 18px;
    }

    .adventure-card {
      min-height: 210px;
      padding: 20px;
    }

    .character-mark {
      display: grid;
      place-items: center;
      width: 48px;
      height: 48px;
      margin-bottom: 16px;
      border-radius: 50%;
      background: rgba(127, 166, 80, 0.16);
      color: #211a12;
      font-size: 1.6rem;
    }

    .adventure-card h3,
    .mission-card h3 {
      margin-bottom: 8px;
      font-size: 1.15rem;
      line-height: 1.2;
    }

    .mission-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 16px;
    }

    .mission-card {
      display: grid;
      align-content: start;
      padding: 20px;
      min-height: 190px;
    }

    .mission-card .button {
      justify-self: start;
      margin-top: 12px;
    }

    .mission-label {
      display: inline-flex;
      align-items: center;
      min-height: 28px;
      margin-bottom: 12px;
      padding: 0 9px;
      border-radius: 999px;
      background: rgba(231, 182, 93, 0.22);
      color: #704d13;
      font-size: 0.8rem;
      font-weight: 900;
    }

    .adventure-play {
      display: grid;
      grid-template-columns: minmax(300px, 460px) 1fr;
      gap: 24px;
      margin-top: 18px;
      padding: 22px;
      align-items: start;
    }

    .adventure-board-wrap {
      border: 8px solid #211a12;
      border-radius: var(--radius);
      overflow: hidden;
      background: #211a12;
      box-shadow: 0 15px 30px rgba(0, 0, 0, 0.22);
    }

    .adventure-board {
      display: grid;
      grid-template-columns: repeat(8, minmax(0, 1fr));
      grid-template-rows: repeat(8, minmax(0, 1fr));
      gap: 0;
      width: 100%;
      aspect-ratio: 1;
      align-items: stretch;
      justify-items: stretch;
      contain: layout paint;
    }

    .adventure-square {
      position: relative;
      display: grid;
      place-items: center;
      width: 100%;
      height: 100%;
      min-width: 0;
      min-height: 0;
      margin: 0;
      box-sizing: border-box;
      aspect-ratio: auto;
      overflow: hidden;
      border: 0;
      padding: 0;
      appearance: none;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(1.35rem, 5vw, 3.35rem);
      line-height: 1;
      cursor: pointer;
      backface-visibility: hidden;
      -webkit-tap-highlight-color: transparent;
    }

    .adventure-square.selected {
      outline: 4px solid rgba(231, 182, 93, 0.86);
      outline-offset: -4px;
    }

    .adventure-square.source-piece {
      box-shadow: inset 0 0 0 4px rgba(231, 182, 93, 0.5);
    }

    .adventure-square.legal-target::after {
      content: "";
      position: absolute;
      width: 34%;
      height: 34%;
      border: 3px solid rgba(127, 166, 80, 0.85);
      border-radius: 50%;
      pointer-events: none;
    }

    .adventure-panel {
      min-width: 0;
    }

    .mission-selector {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
      margin-bottom: 16px;
    }

    .mission-button {
      min-height: 40px;
      padding: 8px 10px;
      border: 1px solid rgba(33, 26, 18, 0.18);
      border-radius: 7px;
      background: #f7efe2;
      color: #211a12;
      font: inherit;
      font-size: 0.86rem;
      font-weight: 900;
      cursor: pointer;
    }

    .mission-button[aria-pressed="true"] {
      border-color: var(--green);
      background: #dfeecf;
    }

    .rules-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 14px;
    }

    .rule-item {
      min-height: 180px;
      padding: 18px;
    }

    .rule-item strong {
      display: block;
      margin-bottom: 9px;
      font-size: 1.05rem;
    }

    .rule-item p {
      margin-bottom: 0;
      font-size: 0.95rem;
    }

    .opening-grid,
    .notation-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .opening-card,
    .notation-card {
