    }

    .opening-body,
    .notation-card {
      padding: 20px;
    }

    .opening-body h3,
    .notation-card h3 {
      margin-bottom: 8px;
      font-size: 1.18rem;
      line-height: 1.2;
    }

    .opening-line {
      display: inline-flex;
      margin-bottom: 12px;
      padding: 6px 9px;
      border-radius: 6px;
      background: rgba(127, 166, 80, 0.14);
      color: var(--green-dark);
      font-size: 0.88rem;
      font-weight: 900;
    }

    .book-lines {
      display: grid;
      gap: 8px;
      margin: 16px 0 0;
      padding: 0;
      list-style: none;
    }

    .book-lines li {
      display: grid;
      gap: 3px;
      padding: 10px;
      border: 1px solid var(--line);
      border-radius: 7px;
      background: rgba(255, 255, 255, 0.06);
    }

    .book-lines code {
      color: var(--soft);
      font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
      font-size: 0.84rem;
      font-weight: 900;
      white-space: normal;
    }

    .book-lines span {
      color: var(--muted);
      font-size: 0.82rem;
    }

    .mini-board {
      display: grid;
      grid-template-columns: repeat(8, minmax(0, 1fr));
      grid-template-rows: repeat(8, minmax(0, 1fr));
      gap: 0;
      width: 100%;
      aspect-ratio: 1;
      align-items: stretch;
      justify-items: stretch;
      padding: 5px;
      border: 1px solid transparent;
      border-radius: 14px 14px 0 0;
      background: #211a12;
      background:
        linear-gradient(135deg, rgba(33, 26, 18, 0.82), rgba(55, 50, 43, 0.64)) padding-box,
        var(--board-frame-gradient) border-box;
      box-shadow: 0 10px 24px rgba(0, 0, 0, 0.22), 0 0 18px var(--board-frame-glow);
      overflow: hidden;
      contain: layout paint;
    }

    .mini-square {
      display: grid;
      place-items: center;
      width: 100%;
      height: 100%;
      min-width: 0;
      min-height: 0;
      box-sizing: border-box;
      aspect-ratio: auto;
      overflow: hidden;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(1rem, 3vw, 2rem);
      line-height: 1;
      user-select: none;
    }

    .notation-grid {
      grid-template-columns: 1.1fr 0.9fr 1fr;
    }

    .notation-list {
      display: grid;
      gap: 10px;
      margin: 16px 0 0;
      padding: 0;
      list-style: none;
    }

    .notation-list li {
      display: grid;
      grid-template-columns: 82px 1fr;
      gap: 12px;
      align-items: start;
      color: var(--muted);
    }

    .notation-list code {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 30px;
      border-radius: 6px;
      background: rgba(255, 255, 255, 0.08);
      color: var(--soft);
      font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
      font-weight: 900;
    }

    .notation-card.callout {
      background:
        linear-gradient(135deg, rgba(127, 166, 80, 0.22), rgba(231, 182, 93, 0.14)),
        var(--panel);
    }

    .books-shell {
      display: grid;
      gap: 18px;
    }

    .book-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
    }

    .book-stat {
      min-height: 88px;
      padding: 15px;
      border: 1px solid rgba(33, 26, 18, 0.14);
      border-radius: var(--radius);
      background: #fff8eb;
    }

    .book-stat strong,
    .book-stat span {
      display: block;
    }

    .book-stat strong {
      color: #211a12;
      font-size: 1.38rem;
      line-height: 1;
    }

    .book-stat span {
      margin-top: 8px;
      color: #5d5144;
      font-size: 0.9rem;
      font-weight: 800;
    }

    .books-controls {
      display: grid;
      grid-template-columns: minmax(220px, 1fr) auto auto auto;
      gap: 12px;
      align-items: end;
    }

    .book-search {
      display: grid;
      gap: 7px;
      color: #2c261f;
      font-weight: 900;
    }

    .book-search input {
      width: 100%;
      min-height: 46px;
      padding: 0 14px;
      border: 1px solid rgba(33, 26, 18, 0.18);
      border-radius: 7px;
      background: #fffdf6;
      color: #211a12;
      font: inherit;
      outline: none;
      transition: border-color 160ms ease, box-shadow 160ms ease;
    }

    .book-search input:focus {
      border-color: var(--green);
      box-shadow: 0 0 0 3px rgba(127, 166, 80, 0.18);
    }

    .book-level-filters {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }

    .book-category-filters {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      padding: 10px;
      border: 1px solid rgba(33, 26, 18, 0.12);
      border-radius: var(--radius);
      background: rgba(255, 248, 235, 0.58);
    }

    .book-filter {
      min-height: 42px;
      padding: 0 12px;
      border: 1px solid rgba(33, 26, 18, 0.17);
      border-radius: 7px;
      background: #f7efe2;
      color: #211a12;
      font: inherit;
      font-size: 0.9rem;
      font-weight: 900;
      cursor: pointer;
      transition: background 160ms ease, border-color 160ms ease, transform 160ms ease;
    }

    .book-filter:hover,
    .book-filter:focus-visible {
      transform: translateY(-1px);
      border-color: var(--green);
      outline: none;
    }

    .book-filter[aria-pressed="true"] {
      border-color: transparent;
      background: var(--green);
      color: #10150d;
    }

    .books-shell .button.secondary {
      border-color: rgba(33, 26, 18, 0.18);
      background: rgba(33, 26, 18, 0.06);
      color: #211a12;
    }

    .books-shell .button.secondary:hover,
    .books-shell .button.secondary:focus-visible {
      background: rgba(33, 26, 18, 0.1);
    }

    .book-verify-note {
      padding: 14px 16px;
      border: 1px solid rgba(127, 166, 80, 0.25);
      border-radius: var(--radius);
      background: rgba(127, 166, 80, 0.12);
      color: #2c261f;
    }

    .book-verify-note strong {
      color: #1f2b16;
    }

    .book-grid {
      display: grid;
      gap: 24px;
    }

    .book-level-section {
      display: grid;
      gap: 14px;
    }

    .book-level-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding-bottom: 10px;
      border-bottom: 1px solid rgba(33, 26, 18, 0.14);
    }

    .book-level-head h3 {
      margin: 0;
      font-size: 1.35rem;
      line-height: 1.15;
    }

    .book-level-head p {
      max-width: 58ch;
      margin: 6px 0 0;
      color: #5d5144;
      font-size: 0.94rem;
    }

    .book-level-head span {
      display: inline-flex;
      align-items: center;
      min-height: 32px;
      padding: 0 10px;
      border-radius: 7px;
      background: rgba(127, 166, 80, 0.14);
      color: var(--green-dark);
      font-size: 0.86rem;
      font-weight: 900;
      white-space: nowrap;
    }

    .book-level-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .book-card {
      position: relative;
      display: grid;
      grid-template-rows: auto 1fr auto;
      min-height: 410px;
      padding: 20px;
      overflow: hidden;
      transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
    }

    .book-card:hover,
    .book-card:focus-within {
      transform: translateY(-3px);
      border-color: rgba(127, 166, 80, 0.46);
      box-shadow: 0 22px 46px rgba(82, 55, 25, 0.18);
    }

    .book-card.is-selected {
      border-color: rgba(95, 127, 58, 0.72);
      box-shadow: 0 20px 48px rgba(95, 127, 58, 0.16);
    }

    .book-card-main {
      display: grid;
      gap: 14px;
      align-content: start;
    }

    .book-card-top {
      display: grid;
      grid-template-columns: 76px minmax(0, 1fr);
      gap: 14px;
      align-items: start;
    }

    .book-cover {
      display: grid;
      place-items: center;
      width: 76px;
      aspect-ratio: 3 / 4;
      border: 1px solid rgba(33, 26, 18, 0.18);
      border-radius: 7px;
      background:
        linear-gradient(90deg, rgba(33, 26, 18, 0.14) 0 13px, transparent 13px),
        linear-gradient(145deg, #7fa650, #f0d9b5 72%);
      color: #211a12;
      font-family: Georgia, "Times New Roman", serif;
      font-size: 1.35rem;
      font-weight: 900;
      letter-spacing: 0;
    }

    .book-cover.intermediate {
      background:
        linear-gradient(90deg, rgba(33, 26, 18, 0.14) 0 13px, transparent 13px),
        linear-gradient(145deg, #6fa8dc, #f0d9b5 74%);
    }

    .book-cover.advanced {
      background:
        linear-gradient(90deg, rgba(33, 26, 18, 0.14) 0 13px, transparent 13px),
        linear-gradient(145deg, #e7b65d, #b58863 76%);
    }

    .book-card-copy {
      min-width: 0;
    }

    .book-free-tag {
      display: inline-flex;
      align-items: center;
      width: fit-content;
      min-height: 28px;
      margin: 8px 0 10px;
      padding: 0 9px;
      border: 1px solid rgba(95, 127, 58, 0.22);
      border-radius: 7px;
      background: rgba(127, 166, 80, 0.16);
      color: #26391a;
      font-size: 0.78rem;
      font-weight: 900;
    }

    .book-card h3,
    .book-detail h3 {
      margin-bottom: 8px;
      font-size: 1.18rem;
      line-height: 1.2;
    }

    .book-detail h4 {
      margin: 18px 0 8px;
      font-size: 1rem;
    }

    .book-card p {
      margin-bottom: 14px;
      font-size: 0.95rem;
    }

    .book-meta {
      display: grid;
      gap: 8px;
      margin: 14px 0;
      color: #5d5144;
      font-size: 0.9rem;
    }

    .book-meta span {
      display: inline-flex;
      align-items: center;
      min-height: 30px;
      padding: 6px 9px;
      border: 1px solid rgba(33, 26, 18, 0.13);
      border-radius: 7px;
      background: rgba(181, 136, 99, 0.1);
    }

    .book-source {
      margin-top: 0;
      color: #5d5144;
      font-size: 0.82rem;
      word-break: break-word;
    }

    .book-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 16px;
    }

    .book-detail[hidden] {
      display: none;
    }

    .book-detail {
      padding: 24px;
      scroll-margin-top: 86px;
    }

    .book-reader,
    .book-admin {
      border: 1px solid rgba(33, 26, 18, 0.16);
      border-radius: var(--radius);
      background: #fff8eb;
      color: #211a12;
      box-shadow: 0 18px 40px rgba(82, 55, 25, 0.12);
    }

    .book-reader[hidden] {
      display: none;
    }

    .book-reader {
      overflow: hidden;
      scroll-margin-top: 86px;
    }

    .reader-toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 14px;
      border-bottom: 1px solid rgba(33, 26, 18, 0.14);
      background: #f7efe2;
    }

    .reader-title {
      min-width: 0;
    }

    .reader-title h3 {
      margin: 0;
      font-size: 1.18rem;
      line-height: 1.2;
    }

    .reader-title p {
      margin: 4px 0 0;
      color: #5d5144;
      font-size: 0.9rem;
    }

    .reader-controls {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
      justify-content: flex-end;
    }

    .reader-font-control {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      min-height: 42px;
      padding: 0 10px;
      border: 1px solid rgba(33, 26, 18, 0.14);
      border-radius: 7px;
      background: #fffdf6;
      color: #2c261f;
      font-weight: 900;
    }

    .reader-font-control input {
      width: 96px;
    }

    .reader-layout {
      display: grid;
      grid-template-columns: minmax(190px, 260px) minmax(0, 1fr);
      min-height: 440px;
    }

    .reader-toc {
      padding: 16px;
      border-right: 1px solid rgba(33, 26, 18, 0.14);
      background: #fbf1e3;
    }

    .reader-toc h4,
    .reader-page h4 {
      margin: 0 0 10px;
      font-size: 1rem;
    }

    .reader-toc-list {
      display: grid;
      gap: 8px;
    }

    .reader-toc-button {
      width: 100%;
      min-height: 40px;
      padding: 8px 10px;
      border: 1px solid rgba(33, 26, 18, 0.14);
      border-radius: 7px;
      background: #fff8eb;
      color: #211a12;
      font: inherit;
      font-weight: 900;
      text-align: left;
      cursor: pointer;
    }

    .reader-toc-button[aria-current="true"] {
      border-color: transparent;
      background: var(--green);
      color: #10150d;
    }

    .reader-page {
      padding: clamp(20px, 4vw, 38px);
      background: #fffdf6;
    }

    .reader-page.dark {
      background: #15120f;
      color: #f7f1e6;
    }

    .reader-page.dark p,
    .reader-page.dark li {
      color: #d8ccb9;
    }

    .reader-page p,
    .reader-page li {
      color: #3c332a;
      line-height: 1.75;
    }

    .reader-page ul {
      display: grid;
      gap: 10px;
      margin: 14px 0 0;
      padding-left: 20px;
    }

    .reader-nav {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 24px;
    }

    .reader-nav .button:disabled {
      cursor: default;
      opacity: 0.55;
      transform: none;
    }

    .reader-status {
      min-height: 28px;
      margin-top: 14px;
      color: #5d5144;
      font-weight: 900;
    }

    .book-admin {
      padding: 18px;
    }

    .book-admin summary {
      cursor: pointer;
      font-weight: 900;
    }

    .book-admin p {
      margin: 10px 0 16px;
      color: #5d5144;
    }

    .admin-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
    }

    .admin-grid label {
      display: grid;
      gap: 6px;
      color: #2c261f;
      font-weight: 900;
    }

    .admin-grid input,
    .admin-grid select,
    .admin-grid textarea {
      width: 100%;
      min-height: 42px;
      padding: 9px 11px;
      border: 1px solid rgba(33, 26, 18, 0.16);
      border-radius: 7px;
      background: #fffdf6;
      color: #211a12;
      font: inherit;
    }

    .admin-grid textarea {
      min-height: 92px;
      resize: vertical;
    }

    .admin-wide {
      grid-column: 1 / -1;
    }

    .admin-list {
      display: grid;
      gap: 8px;
      margin-top: 14px;
    }

    .admin-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 10px;
      border: 1px solid rgba(33, 26, 18, 0.12);
      border-radius: 7px;
      background: #fffdf6;
    }

    .book-detail-grid {
      display: grid;
      grid-template-columns: minmax(220px, 0.85fr) minmax(0, 1.15fr);
      gap: 22px;
      align-items: start;
    }

    .book-detail-list {
      display: grid;
      grid-template-columns: 118px 1fr;
      gap: 10px 14px;
      margin: 16px 0 0;
    }

    .book-detail-list dt {
      color: #2c261f;
      font-weight: 900;
    }

    .book-detail-list dd {
      margin: 0;
      color: #5d5144;
      word-break: break-word;
    }

    .book-detail a {
      color: var(--green-dark);
      font-weight: 900;
      text-decoration: underline;
      text-underline-offset: 3px;
    }

    .book-empty {
      grid-column: 1 / -1;
      padding: 20px;
      border: 1px dashed rgba(33, 26, 18, 0.22);
      border-radius: var(--radius);
      color: #5d5144;
      background: rgba(255, 248, 235, 0.58);
    }

    .video-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
      gap: 16px;
    }

    #videos .wrap {
      counter-reset: video-tier;
    }

    .video-tier {
      counter-increment: video-tier;
      margin-top: 24px;
      padding: 18px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 12% 0%, rgba(231, 182, 93, 0.13), transparent 30%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.045), rgba(127, 166, 80, 0.055)),
        rgba(0, 0, 0, 0.12);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 18px 44px rgba(0, 0, 0, 0.12);
    }

    .video-tier:first-of-type {
      margin-top: 22px;
    }

    .video-tier-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 16px;
      padding-bottom: 12px;
      border-bottom: 1px solid rgba(255, 248, 237, 0.09);
    }

    .video-tier-head h3 {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 0;
      font-size: 1.35rem;
      line-height: 1.15;
    }

    .video-tier-head h3::before {
      content: counter(video-tier);
      display: grid;
      place-items: center;
      width: 32px;
      height: 32px;
      border-radius: 8px;
      background: var(--green);
      color: #10150d;
      font-size: 0.92rem;
      font-weight: 1000;
      flex: 0 0 auto;
    }

    .video-tier-head p {
      max-width: 58ch;
      margin-bottom: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .video-grid.tier-grid {
      grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    }

    .video-watch-path {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 10px;
      margin: 18px 0 8px;
    }

    .video-path-card {
      min-height: 86px;
      display: grid;
      align-content: center;
      gap: 5px;
      padding: 12px;
      border: 1px solid rgba(231, 182, 93, 0.18);
      border-radius: var(--radius);
      background: rgba(231, 182, 93, 0.08);
      transition: transform var(--move-speed) ease, border-color var(--move-speed) ease, background var(--move-speed) ease;
    }

    .video-path-card:hover,
    .video-path-card:focus-visible {
      border-color: rgba(231, 182, 93, 0.5);
      background: rgba(231, 182, 93, 0.13);
      transform: translateY(-2px);
      outline: none;
    }

    .video-path-card strong {
      color: var(--text);
      font-size: 0.94rem;
      font-weight: 1000;
      line-height: 1.15;
    }

    .video-path-card span {
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 800;
      line-height: 1.35;
    }

    .shorts-tier {
      margin-top: 44px;
      padding-top: 34px;
      border-top: 1px solid rgba(255, 248, 237, 0.12);
      scroll-margin-top: 92px;
