    .shorts-title-band p {
      max-width: 68ch;
      margin: 9px 0 0;
      color: var(--muted);
    }

    .shorts-count {
      display: inline-flex;
      align-items: center;
      min-height: 38px;
      padding: 0 12px;
      border: 1px solid rgba(231, 182, 93, 0.42);
      border-radius: 6px;
      background: rgba(231, 182, 93, 0.13);
      color: var(--gold);
      font-weight: 900;
      white-space: nowrap;
    }

    .shorts-toolbar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 14px;
      margin: 0 0 16px;
    }

    .shorts-tabs {
      display: inline-flex;
      flex-wrap: wrap;
      gap: 8px;
    }

    .shorts-progress-controls {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .shorts-audio-controls {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .shorts-tab,
    .shorts-sound-toggle,
    .shorts-resume {
      min-height: 38px;
      padding: 0 12px;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 6px;
      background: rgba(255, 255, 255, 0.07);
      color: var(--muted);
      font: inherit;
      font-size: 0.9rem;
      font-weight: 900;
      cursor: pointer;
      transition: background 160ms ease, color 160ms ease, border-color 160ms ease;
    }

    .shorts-tab:hover,
