      border-radius: 14px;
      padding: 2px;
      background: var(--board-frame-solution-gradient);
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask-composite: xor;
      mask-composite: exclude;
      opacity: 0.82;
      animation: solutionBorderSweep 1.8s linear infinite;
    }

    .play-shell {
      grid-template-columns: minmax(360px, 560px) minmax(420px, 1fr);
      max-width: min(100%, 1540px);
      margin-inline: auto;
      gap: 22px;
      padding: 18px;
      border: 1px solid rgba(255, 248, 237, 0.1);
