    .match-player-card {
      position: relative;
      grid-area: white-seat;
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) auto;
      gap: 6px 9px;
      align-items: center;
      width: fit-content;
      max-width: min(100%, 340px);
      justify-self: center;
      padding: 7px 9px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 16px;
      background:
        linear-gradient(135deg, rgba(255, 248, 237, 0.08), rgba(127, 166, 80, 0.08)),
        rgba(32, 27, 22, 0.78);
      box-shadow: 0 12px 26px rgba(0, 0, 0, 0.2);
      backdrop-filter: blur(10px);
      overflow: visible;
      transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease, background 220ms ease;
