    .match-player-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(115deg, transparent 0 38%, rgba(255, 248, 237, 0.08) 50%, transparent 62% 100%);
      opacity: 0;
      pointer-events: none;
      transition: opacity 220ms ease;
    }

    .match-player-card:hover,
    .match-player-card:focus-within {
      transform: translateY(-2px);
      border-color: rgba(231, 182, 93, 0.34);
      background:
        linear-gradient(135deg, rgba(255, 248, 237, 0.1), rgba(127, 166, 80, 0.11)),
        rgba(32, 27, 22, 0.82);
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28), 0 0 24px rgba(231, 182, 93, 0.1);
    }

    .match-player-card:hover::before,
    .match-player-card:focus-within::before {
      opacity: 1;
    }

    .ai-player-card {
      --ai-rarity: #cfd5d8;
      position: relative;
      grid-area: black-seat;
      overflow: visible;
      width: fit-content;
      max-width: min(100%, 340px);
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) auto;
      gap: 6px 9px;
      align-items: center;
      justify-self: center;
      padding: 7px 9px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 16px;
      background:
        linear-gradient(135deg, rgba(255, 248, 237, 0.08), rgba(127, 166, 80, 0.08)),
        rgba(32, 27, 22, 0.78);
      box-shadow: 0 12px 26px rgba(0, 0, 0, 0.2);
      backdrop-filter: blur(10px);
      transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease, background 220ms ease;
    }

    .ai-player-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(115deg, transparent 0 38%, rgba(255, 248, 237, 0.08) 50%, transparent 62% 100%);
      opacity: 0;
      pointer-events: none;
      transition: opacity 220ms ease;
    }

    .ai-player-card:hover,
    .ai-player-card:focus-within {
      transform: translateY(-2px);
      border-color: rgba(231, 182, 93, 0.34);
      background:
        linear-gradient(135deg, rgba(255, 248, 237, 0.1), rgba(127, 166, 80, 0.11)),
        rgba(32, 27, 22, 0.82);
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28), 0 0 24px rgba(231, 182, 93, 0.1);
    }

    .ai-player-card:hover::before,
    .ai-player-card:focus-within::before {
      opacity: 1;
    }

    .ai-player-card[data-ai-rarity="Common"] { --ai-rarity: #cfd5d8; }
    .ai-player-card[data-ai-rarity="Rare"] { --ai-rarity: #6fa8dc; }
    .ai-player-card[data-ai-rarity="Epic"] { --ai-rarity: #ae87ff; }
    .ai-player-card[data-ai-rarity="Legendary"] { --ai-rarity: #ffd36b; }
    .ai-player-card[data-ai-rarity="Mythic"] { --ai-rarity: #ff705c; }
    .ai-player-card[data-ai-rarity="Divine"] { --ai-rarity: #9ee7ff; }
    .ai-player-card.is-active {
      border-color: color-mix(in srgb, var(--ai-rarity) 56%, rgba(127, 166, 80, 0.56));
      box-shadow: 0 16px 34px rgba(0,0,0,.24), 0 0 28px color-mix(in srgb, var(--ai-rarity) 22%, transparent);
    }
    .ai-player-card.is-thinking .ai-player-avatar { animation: matchAvatarThinking 1.25s ease-in-out infinite; }
    .ai-player-card.is-winner { --ai-rarity: #ffd36b; }
    .ai-player-card.is-loser { --ai-rarity: #8b8f94; filter: grayscale(.25); }

    .ai-player-avatar {
      position: relative;
      z-index: 1;
      grid-row: 1 / 3;
      width: 38px;
      height: 38px;
      display: grid;
      place-items: center;
      border: 1px solid color-mix(in srgb, var(--ai-rarity) 44%, rgba(231, 182, 93, 0.42));
      border-radius: 12px;
      background: linear-gradient(135deg, color-mix(in srgb, var(--ai-rarity) 18%, rgba(231, 182, 93, 0.14)), rgba(127, 166, 80, 0.18));
      box-shadow: inset 0 1px 0 rgba(255,255,255,.12);
