    }

    .ai-player-main {
      position: relative;
      z-index: 1;
      min-width: 0;
      display: grid;
      gap: 1px;
    }

    .ai-player-main strong {
      display: flex;
      align-items: center;
      gap: 7px;
      min-width: 0;
      font-weight: 1000;
    }

    .ai-player-main small,
    .ai-player-last {
      color: var(--muted);
      font-weight: 850;
      font-size: .72rem;
    }

    .ai-player-move,
    .ai-player-status,
    .ai-player-last {
      position: relative;
      z-index: 1;
      padding: 6px 9px;
      border-radius: 999px;
      background: rgba(0,0,0,.18);
      border: 1px solid rgba(255,255,255,.08);
      font-size: .72rem;
      font-weight: 950;
      white-space: nowrap;
    }

    .ai-player-move,
    .ai-player-status {
      justify-self: end;
    }

    .ai-player-status {
      grid-column: 3;
      grid-row: 2;
    }

    .ai-player-last {
      grid-column: 2;
      grid-row: 2;
