      overflow: hidden;
      text-overflow: ellipsis;
    }

    .ai-player-status { color: var(--green); }
    .ai-player-card.is-thinking .ai-player-status { color: var(--gold); }

    .match-player-card,
    .ai-player-card {
      width: min(100%, 380px);
      min-height: 84px;
      grid-template-columns: 46px minmax(0, 1fr) auto;
      grid-template-rows: auto auto;
      gap: 6px 11px;
      padding: 9px 11px;
      align-items: center;
    }

    .match-player-avatar,
    .ai-player-avatar {
      grid-column: 1;
      grid-row: 1 / 3;
      width: 46px;
      height: 46px;
      border-radius: 13px;
    }

    .match-player-main,
    .ai-player-main {
      grid-column: 2;
      grid-row: 1;
      align-self: end;
      min-width: 0;
      display: grid;
      gap: 2px;
    }

    .match-player-main strong,
    .ai-player-main strong {
      font-size: 0.92rem;
      line-height: 1.1;
    }

    .match-player-main small,
    .ai-player-main small {
      font-size: 0.68rem;
      line-height: 1.1;
    }

    .match-player-timer,
    .ai-player-timer,
    .ai-player-move {
      grid-column: 3;
      grid-row: 1;
      align-self: center;
      justify-self: end;
      min-width: 52px;
      min-height: 31px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border-radius: 999px;
    }

    .match-player-meta {
      grid-column: 2 / 3;
      grid-row: 2;
      display: flex;
      align-items: center;
      gap: 6px;
      min-width: 0;
      overflow: visible;
    }

    .match-player-pill {
      min-height: 25px;
      padding: 0 10px;
      white-space: nowrap;
    }

    .match-player-pill[data-match-rating],
    .match-player-pill.is-premium {
      display: none;
    }

    .ai-player-last {
      grid-column: 2;
      grid-row: 2;
      justify-self: start;
      max-width: 142px;
      min-height: 28px;
      display: inline-flex;
      align-items: center;
    }

    .ai-player-status {
      grid-column: 3;
      grid-row: 2;
      min-height: 28px;
      display: inline-flex;
      align-items: center;
    }

    @keyframes aiHeaderShine {
      0%, 100% { transform: translateX(-55%); opacity: .16; }
      50% { transform: translateX(55%); opacity: .58; }
    }

    @media (max-width: 560px) {
      .ai-player-card {
        grid-template-columns: auto minmax(0, 1fr) auto;
      }

      .ai-player-last {
        grid-column: 2 / -1;
      }
    }

    .match-player-card.is-entering {
      animation: matchCardEntrance 520ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .match-player-card.is-entering .match-player-avatar {
      animation: matchAvatarEntrance 620ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .match-player-card.is-player-turn {
      border-color: rgba(127, 166, 80, 0.56);
      box-shadow: 0 16px 34px rgba(0, 0, 0, 0.24), 0 0 28px rgba(127, 166, 80, 0.2);
    }

    .match-player-card.is-player-turn .match-player-avatar {
      animation: matchAvatarThinking 1.65s ease-in-out infinite;
    }

    .match-player-card.is-player-turn .match-player-name-line::after,
    .match-player-card.is-coach-thinking .match-player-name-line::after {
      content: "";
      width: 7px;
      height: 7px;
      flex: 0 0 auto;
      border-radius: 999px;
      background: var(--green);
      box-shadow: 0 0 0 4px rgba(127, 166, 80, 0.16), 0 0 14px rgba(127, 166, 80, 0.42);
      animation: matchThinkingDot 1.2s ease-in-out infinite;
    }

    .match-player-card.is-coach-thinking .match-player-name-line::after {
      background: var(--gold);
      box-shadow: 0 0 0 4px rgba(231, 182, 93, 0.14), 0 0 14px rgba(231, 182, 93, 0.4);
    }

    .match-player-avatar {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border: 1px solid rgba(231, 182, 93, 0.42);
      border-radius: 12px;
      background: linear-gradient(135deg, rgba(231, 182, 93, 0.2), rgba(127, 166, 80, 0.18));
      color: var(--text);
      font-size: 1.22rem;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
    }

    .match-player-hover-stats {
      display: none;
      position: absolute;
      left: calc(100% + 8px);
      top: 50%;
      z-index: 6;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 6px;
      width: 220px;
      padding: 9px;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 12px;
      background: rgba(23, 20, 16, 0.92);
      box-shadow: 0 16px 32px rgba(0, 0, 0, 0.3), 0 0 22px rgba(231, 182, 93, 0.12);
      opacity: 0;
      pointer-events: none;
      transform: translate(-6px, -50%) scale(0.98);
      transition: opacity 180ms ease, transform 180ms ease;
      backdrop-filter: blur(12px);
    }

    .match-player-card:hover .match-player-hover-stats,
    .match-player-card:focus-within .match-player-hover-stats {
      opacity: 0;
      transform: translate(-6px, -50%) scale(0.98);
    }

    .match-player-hover-stats span {
      display: grid;
      gap: 2px;
      min-width: 0;
      color: var(--muted);
      font-size: 0.62rem;
      font-weight: 900;
      text-transform: uppercase;
    }

    .match-player-hover-stats strong {
      color: var(--text);
      font-size: 0.86rem;
      line-height: 1;
      text-transform: none;
    }

    .leaderboard-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .leaderboard-toolbar {
      display: flex;
