    .leaderboard-card {
      position: relative;
      overflow: hidden;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 90% 0%, rgba(231, 182, 93, 0.16), transparent 34%),
