    }

    .store-wallet {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 12px;
      align-items: center;
      padding: 16px;
      border: 1px solid rgba(231, 182, 93, 0.28);
      border-radius: var(--radius);
      background:
        linear-gradient(120deg, rgba(255,255,255,.08), transparent 28%, rgba(231,182,93,.1) 58%, transparent 76%),
        radial-gradient(circle at 92% 0%, rgba(231, 182, 93, 0.22), transparent 28%),
        linear-gradient(135deg, rgba(127, 166, 80, 0.16), rgba(111, 168, 220, 0.12)),
        var(--panel);
      box-shadow: 0 22px 54px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.08);
    }

    .store-wallet h3,
    .store-wallet p,
    .store-status {
      margin: 0;
    }

    .store-balance {
      min-width: 128px;
      display: grid;
      justify-items: center;
      padding: 12px;
      border: 1px solid rgba(231, 182, 93, 0.32);
      border-radius: var(--radius);
      background: rgba(231, 182, 93, 0.13);
      color: var(--gold);
      font-weight: 1000;
    }

    .store-balance strong {
      color: var(--text);
      font-size: 1.45rem;
      line-height: 1;
    }

    .store-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 14px;
      align-items: stretch;
    }

    .store-card {
      position: relative;
      overflow: hidden;
      display: grid;
      grid-template-rows: auto auto minmax(3.2em, auto) auto auto;
      gap: 11px;
      align-content: start;
      padding: 15px;
      border: 1px solid color-mix(in srgb, var(--rarity-color, var(--line)) 42%, var(--line));
      border-radius: 18px;
      background:
        radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--rarity-color, var(--gold)) 18%, transparent), transparent 34%),
        linear-gradient(145deg, rgba(255,255,255,.075), rgba(255,255,255,.025) 36%, rgba(0,0,0,.12)),
        color-mix(in srgb, var(--panel) 92%, #111);
      box-shadow: 0 18px 42px rgba(0,0,0,.2), inset 0 1px 0 rgba(255,255,255,.08);
      transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease, filter 220ms ease;
      isolation: isolate;
    }

    .store-card::before {
      content: "";
      position: absolute;
      inset: -1px;
      z-index: -1;
      border-radius: inherit;
      background: linear-gradient(120deg, transparent 0 28%, rgba(255,255,255,.14), transparent 54% 100%);
      opacity: 0;
      transform: translateX(-35%);
      transition: opacity 220ms ease, transform 520ms ease;
      pointer-events: none;
