    .store-card.is-owned {
      border-color: rgba(127, 166, 80, 0.46);
    }

    .store-card.is-equipped {
      box-shadow: inset 0 0 0 2px rgba(231, 182, 93, 0.34), 0 0 34px rgba(231,182,93,.16);
      animation: storeEquipPop 420ms ease both;
