    .store-card[data-rarity="Epic"] { --rarity-color: #ae87ff; }
    .store-card[data-rarity="Legendary"] { --rarity-color: #ffd36b; }
    .store-card[data-rarity="Mythic"] { --rarity-color: #ff7adf; }
    .store-card[data-rarity="Divine"] { --rarity-color: #fff2b8; }

    .store-card[data-rarity="Legendary"] .store-meta span:first-child,
    .store-card[data-rarity="Mythic"] .store-meta span:first-child,
