      box-shadow: 0 0 18px color-mix(in srgb, var(--rarity-color) 24%, transparent);
    }

    .store-card[data-rarity="Legendary"] .store-preview,
    .store-card[data-rarity="Mythic"] .store-preview,
    .store-card[data-rarity="Divine"] .store-preview {
      background:
        radial-gradient(circle at 22% 18%, rgba(255,255,255,.18), transparent 24%),
        radial-gradient(circle at 78% 16%, color-mix(in srgb, var(--rarity-color) 30%, transparent), transparent 32%),
        linear-gradient(145deg, rgba(255,255,255,.1), rgba(0,0,0,.18));
      box-shadow: inset 0 1px 0 rgba(255,255,255,.18), 0 0 34px color-mix(in srgb, var(--rarity-color) 30%, transparent);
    }

    .store-card[data-rarity="Mythic"] .store-preview {
      background:
        conic-gradient(from 0deg, rgba(255,122,223,.28), rgba(92,255,224,.18), rgba(174,135,255,.28), rgba(255,122,223,.28)),
        radial-gradient(circle at 50% 20%, rgba(255,255,255,.16), transparent 30%),
        rgba(0,0,0,.16);
      animation: mythicPreviewAura 5.2s linear infinite;
    }

    .store-card[data-rarity="Divine"] .store-preview {
      background:
        conic-gradient(from 0deg, rgba(255,248,214,.34), rgba(158,231,255,.2), rgba(255,211,107,.28), rgba(255,248,214,.34)),
        radial-gradient(circle at 50% 12%, rgba(255,255,255,.32), transparent 28%),
        rgba(0,0,0,.12);
      animation: divinePreviewAura 4.6s ease-in-out infinite;
    }

    .store-card[data-rarity="Legendary"] .store-preview::before,
    .store-card[data-rarity="Mythic"] .store-preview::before,
    .store-card[data-rarity="Divine"] .store-preview::before {
      content: "";
      position: absolute;
      inset: 10px;
      border-radius: 16px;
      background:
        radial-gradient(circle at 18% 74%, rgba(255,255,255,.72) 0 1px, transparent 3px),
        radial-gradient(circle at 78% 28%, color-mix(in srgb, var(--rarity-color) 76%, white) 0 1px, transparent 4px),
        linear-gradient(105deg, transparent 0 34%, rgba(255,255,255,.22), transparent 64%);
      opacity: .72;
      animation: premiumStoreSweep 4.8s ease-in-out infinite;
      pointer-events: none;
    }

    @keyframes premiumStoreSweep {
      0%, 100% { transform: translate3d(-6%, 3%, 0); opacity: .35; }
      50% { transform: translate3d(6%, -3%, 0); opacity: .86; }
    }

    @keyframes mythicPreviewAura {
      from { filter: hue-rotate(0deg) saturate(1.08); }
      to { filter: hue-rotate(360deg) saturate(1.22); }
    }

    @keyframes divinePreviewAura {
      0%, 100% { filter: brightness(1.05) saturate(1.08); box-shadow: inset 0 1px 0 rgba(255,255,255,.22), 0 0 28px rgba(255,211,107,.22); }
      50% { filter: brightness(1.22) saturate(1.2); box-shadow: inset 0 1px 0 rgba(255,255,255,.32), 0 0 44px rgba(255,248,214,.34); }
    }

    .store-showcase {
      display: grid;
      grid-template-columns: repeat(5, minmax(150px, 1fr));
      gap: 10px;
