      box-shadow: 0 22px 46px rgba(0,0,0,.26), 0 0 24px color-mix(in srgb, var(--rarity-color, var(--gold)) 18%, transparent);
    }

    .store-showcase-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(110deg, transparent 0 42%, rgba(255,255,255,.16), transparent 66%);
