    .tutorial-files {
      grid-column: 2;
      display: grid;
      grid-template-columns: repeat(8, minmax(0, 1fr));
      place-items: center;
    }

    .tutorial-files-top {
      grid-row: 1;
    }

    .tutorial-files-bottom {
      grid-row: 3;
    }

    .tutorial-ranks {
      grid-row: 2;
      display: grid;
      grid-template-rows: repeat(8, minmax(0, 1fr));
      place-items: center;
    }

    .tutorial-ranks-left {
      grid-column: 1;
    }

    .tutorial-ranks-right {
      grid-column: 3;
    }

    .tutorial-board {
      grid-column: 2;
      grid-row: 2;
      display: grid;
      grid-template-columns: repeat(8, minmax(0, 1fr));
      grid-template-rows: repeat(8, minmax(0, 1fr));
      gap: 0;
      align-items: stretch;
      justify-items: stretch;
      aspect-ratio: 1;
      overflow: hidden;
      border: 7px solid rgba(80, 55, 32, 0.9);
      border-radius: 14px;
      box-shadow: 0 18px 38px rgba(0, 0, 0, 0.28);
      contain: layout paint;
      isolation: isolate;
    }

    .tutorial-square {
      position: relative;
      display: grid;
      place-items: center;
      width: 100%;
      height: 100%;
      min-width: 0;
      min-height: 0;
      margin: 0;
      box-sizing: border-box;
      overflow: hidden;
      border: 0;
      appearance: none;
      color: inherit;
      font: inherit;
      font-size: clamp(1.45rem, 5vw, 3.1rem);
      cursor: pointer;
      line-height: 1;
      backface-visibility: hidden;
      -webkit-tap-highlight-color: transparent;
    }

    .tutorial-square .piece-symbol {
      position: relative;
      z-index: 2;
      width: 100%;
      height: 100%;
      font-size: 0.82em;
      transform: none;
      text-shadow: 0 1px 1px rgba(0, 0, 0, 0.28);
    }

    .tutorial-square.light { background-color: var(--board-light); background-image: var(--board-light-texture); }
    .tutorial-square.dark { background-color: var(--board-dark); background-image: var(--board-dark-texture); }

    .tutorial-square.is-source::after,
    .tutorial-square.is-target::after,
    .tutorial-square.is-selected::after,
    .tutorial-square.is-last::after {
      content: "";
      position: absolute;
      inset: 12%;
      z-index: 1;
      border-radius: 999px;
      pointer-events: none;
    }

    .tutorial-square.is-source::after {
      border: 3px solid rgba(255, 211, 107, 0.78);
      box-shadow: 0 0 18px rgba(255, 211, 107, 0.36);
    }

    .tutorial-square.is-target::after {
      background: rgba(127, 166, 80, 0.42);
      transform: scale(0.52);
      transition: transform 180ms ease;
    }

    .tutorial-square.is-target:hover::after,
    .tutorial-square.is-selected::after {
      transform: scale(0.82);
      background: rgba(231, 182, 93, 0.46);
    }

    .tutorial-square.is-last::after {
      border-radius: 8px;
      border: 3px solid rgba(111, 168, 220, 0.74);
    }

    .tutorial-info {
      display: grid;
      gap: 8px;
    }

    .tutorial-info h3,
    .tutorial-info p,
    .tutorial-coach h3,
    .tutorial-coach p {
      margin: 0;
    }

    .tutorial-actions,
    .tutorial-quiz,
    .tutorial-progress {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
    }

    .tutorial-progress {
      justify-content: space-between;
      color: var(--muted);
      font-weight: 900;
    }

    .tutorial-progress-bar {
      flex: 1 1 180px;
      height: 9px;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.1);
    }

    .tutorial-progress-bar span {
      display: block;
      width: var(--tutorial-progress, 0%);
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--green), var(--gold));
      transition: width 260ms ease;
    }

    .tutorial-quiz button {
      flex: 1 1 150px;
    }

    .tutorial-coach {
      display: grid;
      gap: 12px;
      position: sticky;
      top: 92px;
      align-self: start;
      grid-column: 2;
      min-width: 0;
    }

    .tutorial-reward {
      display: grid;
      gap: 8px;
      padding: 12px;
      border: 1px solid rgba(231, 182, 93, 0.28);
      border-radius: 10px;
      background: rgba(231, 182, 93, 0.1);
      color: var(--gold);
      font-weight: 1000;
    }

    .academy-shell {
      display: grid;
      grid-template-columns: minmax(0, 1.45fr) minmax(260px, 0.75fr);
      gap: 16px;
      align-items: stretch;
    }

    .academy-hero-card,
    .academy-panel,
    .academy-card,
    .academy-quiz {
      border: 1px solid rgba(231, 182, 93, 0.22);
      border-radius: var(--radius);
      background:
        linear-gradient(135deg, rgba(231, 182, 93, 0.13), rgba(127, 166, 80, 0.08)),
        color-mix(in srgb, var(--panel) 91%, transparent);
      box-shadow: var(--shadow);
    }

    .academy-hero-card,
    .academy-panel,
    .academy-quiz {
      padding: clamp(16px, 3vw, 24px);
    }

    .academy-hero-card {
      display: grid;
      gap: 14px;
      overflow: hidden;
      position: relative;
    }

    .academy-hero-card::after {
      content: "";
      position: absolute;
      inset: auto -12% -55% 48%;
      height: 190px;
      border-radius: 999px;
      background: radial-gradient(circle, rgba(231, 182, 93, 0.18), transparent 68%);
      pointer-events: none;
    }

    .academy-hero-card h3,
    .academy-hero-card p,
    .academy-panel p,
    .academy-card p,
    .academy-quiz p {
      margin: 0;
    }

    .academy-meter {
      display: grid;
      gap: 8px;
      max-width: 520px;
      font-weight: 1000;
      color: var(--soft);
    }

    .academy-meter div {
      height: 11px;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.1);
    }

    .academy-meter i {
      display: block;
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--green), var(--gold));
      transition: width 320ms ease;
    }

    .academy-actions,
    .academy-card-actions,
    .academy-quiz-options {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
    }

    .academy-mini-stats {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }

    .academy-mini-stats span,
    .academy-reward {
      display: grid;
      gap: 4px;
      min-height: 76px;
      padding: 12px;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.055);
    }

    .academy-mini-stats strong {
      color: var(--gold);
      font-size: 1.25rem;
    }

    .academy-mini-stats small,
    .academy-card small {
      color: var(--muted);
      font-weight: 900;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .academy-reward {
      margin-top: 12px;
      min-height: auto;
      color: var(--soft);
      font-weight: 900;
    }

    .academy-track {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
      gap: 12px;
      margin-top: 16px;
    }

    .academy-card {
      display: grid;
      gap: 10px;
      min-height: 190px;
      padding: 16px;
      color: var(--text);
      text-decoration: none;
      transition: transform 220ms ease, border-color 220ms ease, background 220ms ease;
    }

    .academy-card:hover,
    .academy-card:focus-visible {
      transform: translateY(-3px);
      border-color: rgba(231, 182, 93, 0.55);
      background:
        linear-gradient(135deg, rgba(231, 182, 93, 0.2), rgba(127, 166, 80, 0.12)),
        color-mix(in srgb, var(--panel) 88%, transparent);
    }

    .academy-card strong {
      font-size: 1.04rem;
    }

    .academy-card .academy-step-number {
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 999px;
      background: var(--green);
      color: #12120f;
      font-weight: 1000;
    }

    .academy-quiz {
      display: grid;
      gap: 12px;
      margin-top: 16px;
    }

    .academy-quiz h3 {
      margin: 0;
    }

    .academy-quiz-options button {
      flex: 1 1 180px;
    }

    @media (max-width: 820px) {
      .academy-shell {
        grid-template-columns: 1fr;
      }

      .academy-mini-stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .academy-card {
        min-height: auto;
      }
    }

    .store-status {
      color: var(--gold);
      font-weight: 900;
    }

    .captured-row {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }

    .captured-row > div,
    .move-history,
    .guided-review {
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: var(--radius);
      background: rgba(0, 0, 0, 0.14);
      padding: 12px;
    }

    .captured-row strong {
      display: block;
      margin-bottom: 6px;
      font-size: 0.84rem;
    }

    .captured-pieces {
      min-height: 34px;
      font-family: Georgia, "Times New Roman", serif;
      font-size: 1.55rem;
      line-height: 1.15;
    }

    .guided-review {
      display: grid;
      gap: 10px;
    }

    .guided-review[hidden] {
      display: none;
    }

    .post-game-flow {
      display: grid;
      gap: 12px;
      border: 1px solid rgba(231, 182, 93, 0.34);
      border-radius: 18px;
      padding: 16px;
      background:
        radial-gradient(circle at 8% 0%, rgba(231, 182, 93, 0.18), transparent 34%),
        linear-gradient(145deg, rgba(255, 248, 237, 0.08), rgba(0, 0, 0, 0.2));
      box-shadow: 0 16px 36px rgba(0, 0, 0, 0.2);
      animation: postGameEnter 260ms ease both;
    }

    .post-game-flow[hidden] { display: none; }

    .post-game-head {
      display: flex;
      gap: 11px;
      align-items: center;
    }

    .post-game-mark {
      display: grid;
      place-items: center;
      flex: 0 0 40px;
      width: 40px;
      height: 40px;
      border: 1px solid rgba(255, 211, 107, 0.52);
      border-radius: 12px;
      color: #211609;
      background: linear-gradient(135deg, #ffd36b, #8cb55b);
      font-weight: 1000;
    }

    .post-game-head small,
    .post-game-head p {
      display: block;
      margin: 0;
      color: var(--muted);
      line-height: 1.35;
    }

    .post-game-head strong { font-size: 1.05rem; }

    .post-game-actions {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
    }

    .post-game-actions .button { min-height: 42px; }

    .post-game-history {
      display: grid;
      gap: 7px;
      padding-top: 10px;
      border-top: 1px solid rgba(255, 248, 237, 0.1);
    }

    .post-game-history[hidden] { display: none; }

    .post-game-history button {
      width: 100%;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 10px;
      padding: 9px 10px;
      color: var(--soft);
      background: rgba(0, 0, 0, 0.16);
      text-align: left;
      cursor: pointer;
    }

    .post-game-history button:hover,
    .post-game-history button:focus-visible {
      border-color: rgba(231, 182, 93, 0.58);
      color: var(--text);
    }

    @keyframes postGameEnter {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .premium-review {
      display: grid;
      gap: 14px;
      border: 1px solid rgba(231, 182, 93, 0.34);
      border-radius: 18px;
      padding: 16px;
      background:
        radial-gradient(circle at 8% 0%, rgba(231, 182, 93, 0.2), transparent 30%),
        radial-gradient(circle at 94% 14%, rgba(127, 166, 80, 0.16), transparent 34%),
        linear-gradient(135deg, rgba(255, 248, 237, 0.08), rgba(0, 0, 0, 0.18)),
        rgba(18, 16, 13, 0.72);
      box-shadow: 0 20px 46px rgba(0, 0, 0, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.09);
      backdrop-filter: blur(14px);
    }

    .premium-review[hidden] {
      display: none;
    }

    .premium-review-head,
    .review-controls {
      display: flex;
      gap: 8px;
      align-items: center;
      flex-wrap: wrap;
    }

    .premium-review-head {
      justify-content: space-between;
      padding-bottom: 10px;
      border-bottom: 1px solid rgba(255, 248, 237, 0.09);
    }

    .premium-review-head strong {
      font-size: clamp(1rem, 2vw, 1.35rem);
    }

    .premium-review-head small {
      display: block;
      margin-top: 3px;
      color: var(--muted);
      line-height: 1.35;
    }

    .review-graph {
      display: grid;
      grid-template-columns: repeat(var(--review-move-count, 1), minmax(3px, 1fr));
      align-items: center;
      gap: 6px;
      min-height: 46px;
      padding: 9px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 14px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.055), transparent),
        rgba(0, 0, 0, 0.22);
      overflow: hidden;
    }

    .review-graph span {
      min-width: 0;
      align-self: end;
      height: var(--review-eval-height, 44%);
      min-height: 8px;
      border-radius: 999px;
      background: var(--review-marker, #ffd36b);
      opacity: 0.72;
      transition: height 260ms ease, opacity 160ms ease, transform 160ms ease, box-shadow 160ms ease;
    }

    .review-graph span:hover {
      opacity: 1;
      transform: translateY(-2px);
    }

    .review-summary-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
    }

    .review-summary-card,
    .review-move-chip {
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 14px;
      background: linear-gradient(145deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.025));
      padding: 10px;
    }

    .review-summary-card strong,
    .review-move-chip strong {
      display: block;
      color: var(--gold);
      font-size: 0.78rem;
      text-transform: uppercase;
    }

    .review-summary-card span,
    .review-move-chip span {
      color: var(--soft);
      font-size: 0.9rem;
      line-height: 1.35;
    }

    .review-key-row {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 8px;
    }

    .review-key-button {
      min-height: 42px;
      border: 1px solid rgba(231, 182, 93, 0.24);
      border-radius: 999px;
      color: var(--text);
      background: rgba(255, 248, 237, 0.065);
      font-weight: 900;
      cursor: pointer;
      transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
    }

    .review-key-button:hover,
    .review-key-button:focus-visible {
      transform: translateY(-1px);
      border-color: rgba(231, 182, 93, 0.58);
      background: rgba(231, 182, 93, 0.14);
    }

    .review-compare-row {
      display: grid;
      grid-template-columns: auto auto auto minmax(150px, 1fr);
      gap: 8px;
      align-items: center;
      padding: 8px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 14px;
      background: rgba(0, 0, 0, 0.16);
    }

    .review-compare-button {
      border: 1px solid rgba(231, 182, 93, 0.28);
      border-radius: 999px;
      padding: 8px 12px;
      color: var(--text);
      background: rgba(255, 248, 237, 0.06);
      font-weight: 900;
      cursor: pointer;
    }

    .review-compare-button[aria-pressed="true"] {
      color: #241b0d;
      background: linear-gradient(135deg, #ffd36b, #7fa650);
      box-shadow: 0 0 18px rgba(231, 182, 93, 0.22);
    }

    #reviewWhyText {
      color: var(--soft);
      font-size: 0.9rem;
      line-height: 1.35;
    }

    .review-move-list {
      display: grid;
      gap: 7px;
      max-height: 250px;
      overflow: auto;
      scrollbar-width: thin;
    }

    .review-move-chip {
      display: grid;
      gap: 4px;
      cursor: pointer;
      text-align: left;
    }

    .review-move-chip[aria-current="true"] {
      border-color: rgba(231, 182, 93, 0.62);
      background: rgba(127, 166, 80, 0.15);
      box-shadow: 0 0 18px rgba(231, 182, 93, 0.16);
    }

    .review-brilliant,
    .review-great,
    .review-best,
    .review-excellent,
    .review-opening-book {
      border-color: rgba(255, 211, 107, 0.38);
    }

    .review-good,
    .review-forced {
      border-color: rgba(127, 166, 80, 0.36);
    }

    .review-mistake,
    .review-blunder,
    .review-inaccuracy,
    .review-missed-win {
      border-color: rgba(255, 112, 92, 0.34);
    }

    .review-move-chip::after {
      content: attr(data-review-label);
      justify-self: start;
      border-radius: 999px;
      padding: 2px 8px;
      color: var(--text);
      background: rgba(255, 248, 237, 0.08);
      font-size: 0.68rem;
      font-weight: 900;
    }

    .play-board-wrap {
      position: relative;
    }

    .review-arrow-layer {
      position: absolute;
      inset: 0;
      z-index: 3;
      pointer-events: none;
      overflow: hidden;
      width: 100%;
      height: 100%;
      display: block;
      border-radius: inherit;
      contain: layout paint;
    }

    .review-arrow-line {
      stroke: rgba(255, 211, 107, 0.88);
      stroke-width: 0.12;
      stroke-linecap: round;
      vector-effect: non-scaling-stroke;
      filter: drop-shadow(0 0 8px rgba(231, 182, 93, 0.34));
      animation: reviewArrowDraw 520ms ease both;
    }

    .review-arrow-line.is-best {
      stroke: rgba(93, 191, 255, 0.92);
      stroke-width: 0.105;
      filter: drop-shadow(0 0 10px rgba(93, 191, 255, 0.46));
      animation: reviewArrowDraw 520ms ease both, reviewBestArrowPulse 1.6s ease-in-out infinite;
    }

    .review-arrow-line.is-engine {
      stroke-dasharray: 0.22 0.12;
    }

    .play-square.review-from {
      box-shadow: inset 0 0 0 4px rgba(255, 211, 107, 0.42), inset 0 0 24px rgba(255, 211, 107, 0.18);
    }

    .play-square.review-to {
      box-shadow: inset 0 0 0 4px rgba(127, 166, 80, 0.52), inset 0 0 28px rgba(127, 166, 80, 0.22);
    }

    .play-square.review-best {
      animation: reviewBestPulse 1.4s ease-in-out infinite;
    }

    .play-square.review-attack::before {
      content: "";
      position: absolute;
      inset: 31%;
      z-index: 1;
      border-radius: 999px;
      background: rgba(93, 191, 255, 0.34);
      box-shadow: 0 0 18px rgba(93, 191, 255, 0.32);
      pointer-events: none;
      animation: reviewAttackPing 1.35s ease-in-out infinite;
    }

    .play-board-wrap[data-review-tactic] .play-square.review-attack::before {
      background: color-mix(in srgb, var(--review-tactic, #5dbfff) 48%, transparent);
      box-shadow: 0 0 18px color-mix(in srgb, var(--review-tactic, #5dbfff) 52%, transparent);
    }

    .play-board-wrap[data-review-tactic="fork"] { --review-tactic: #ffd36b; }
    .play-board-wrap[data-review-tactic="pin"] { --review-tactic: #74d6ff; }
    .play-board-wrap[data-review-tactic="skewer"] { --review-tactic: #c58cff; }
    .play-board-wrap[data-review-tactic="discovered"] { --review-tactic: #75e4db; }
    .play-board-wrap[data-review-tactic="hanging"] { --review-tactic: #ffb45f; }
    .play-board-wrap[data-review-tactic="mate"] { --review-tactic: #ff6b7a; }

    .play-square.review-engine-from,
    .play-square.review-engine-to {
      box-shadow: inset 0 0 0 3px rgba(93, 191, 255, 0.48), inset 0 0 25px rgba(93, 191, 255, 0.2);
    }

    .play-square.review-engine-to {
      animation: reviewEngineTarget 1.2s ease-in-out infinite;
    }

    @keyframes reviewArrowDraw {
      from { stroke-dasharray: 120; stroke-dashoffset: 120; opacity: 0; }
      to { stroke-dasharray: 120; stroke-dashoffset: 0; opacity: 1; }
    }

    @keyframes reviewBestPulse {
      50% { filter: brightness(1.13) saturate(1.08); }
    }

    @keyframes reviewBestArrowPulse {
      50% { opacity: 0.58; }
    }

    @keyframes reviewAttackPing {
      50% { transform: scale(1.28); opacity: 0.56; }
    }

    @keyframes reviewEngineTarget {
      50% { filter: brightness(1.18) saturate(1.16); }
    }

    @media (max-width: 760px) {
      .review-summary-grid,
      .review-key-row,
      .review-compare-row {
        grid-template-columns: 1fr 1fr;
      }

      #reviewWhyText {
        grid-column: 1 / -1;
      }
    }

    .premium-review {
      position: relative;
      overflow: hidden;
      gap: 12px;
      border-color: rgba(231, 182, 93, 0.26);
      background:
        radial-gradient(circle at 12% 0%, rgba(255, 211, 107, 0.18), transparent 27%),
        radial-gradient(circle at 100% 12%, rgba(93, 191, 255, 0.12), transparent 30%),
        linear-gradient(145deg, rgba(22, 21, 18, 0.94), rgba(37, 32, 25, 0.88));
    }

    .premium-review::before {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: linear-gradient(115deg, transparent 0 34%, rgba(255, 255, 255, 0.08), transparent 64% 100%);
      transform: translateX(-80%);
      animation: reviewPanelShine 7s ease-in-out infinite;
    }

    .premium-review-head {
      position: relative;
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 10px;
      align-items: center;
    }

    .premium-review-title {
      display: flex;
      gap: 10px;
      align-items: center;
      min-width: 0;
    }

    .review-orb {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      border-radius: 14px;
      color: #23190a;
      background: linear-gradient(135deg, #fff4ba, #d79b35);
      box-shadow: 0 12px 28px rgba(231, 182, 93, 0.22);
      font-weight: 1000;
    }

    .review-focus-card {
      position: relative;
      display: grid;
      gap: 12px;
      padding: 16px;
      border: 1px solid color-mix(in srgb, var(--review-accent, #ffd36b), transparent 48%);
      border-radius: 18px;
      background:
        radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--review-accent, #ffd36b), transparent 72%), transparent 30%),
        linear-gradient(145deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.02));
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.08);
      animation: reviewFocusIn 260ms ease both;
      overflow: hidden;
    }

    .review-focus-card::after {
      content: "";
      position: absolute;
      inset: -35%;
      pointer-events: none;
      opacity: 0;
      background: radial-gradient(circle, color-mix(in srgb, var(--review-accent, #ffd36b), transparent 60%) 0 2px, transparent 3px);
      background-size: 42px 42px;
    }

    .review-focus-card.quality-brilliant {
      animation: reviewFocusIn 260ms ease both, reviewGoldSpark 1.35s ease both;
    }

    .review-focus-card.quality-brilliant::after {
      opacity: 0.55;
      animation: reviewSparkDrift 1.2s ease-out both;
    }

    .review-focus-card.quality-best {
      animation: reviewFocusIn 260ms ease both, reviewGreenGlow 1.25s ease both;
    }

    .review-focus-card.quality-mistake,
    .review-focus-card.quality-inaccuracy,
    .review-focus-card.quality-missed-win {
      animation: reviewFocusIn 260ms ease both, reviewOrangePulse 1.05s ease both;
    }

    .review-focus-card.quality-blunder {
      animation: reviewFocusIn 260ms ease both, reviewRedShake 420ms ease both;
    }

    .review-focus-card.quality-opening-book .review-quality-badge::before {
      content: "BOOK";
      display: inline-grid;
      place-items: center;
      min-width: 28px;
      height: 20px;
      border-radius: 5px 7px 7px 5px;
      color: #fff8ed;
      background: linear-gradient(135deg, #5b3925, #d69b45);
      font-size: 0.58rem;
      box-shadow: inset 3px 0 0 rgba(255, 248, 237, 0.45);
      animation: reviewBookFlip 900ms ease both;
    }

    .review-focus-card #reviewWhyText {
      font-size: clamp(0.98rem, 1.5vw, 1.12rem);
      color: var(--text);
      line-height: 1.48;
    }

    .review-focus-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
    }

    .review-quality-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      width: fit-content;
      border-radius: 999px;
      padding: 7px 11px;
      color: #18110a;
      background: linear-gradient(135deg, var(--review-accent, #ffd36b), rgba(255, 255, 255, 0.74));
      font-weight: 1000;
      box-shadow: 0 0 22px color-mix(in srgb, var(--review-accent, #ffd36b), transparent 62%);
    }

    .review-focus-move {
      margin: 0;
      font-size: clamp(1.55rem, 4vw, 2.45rem);
      line-height: 1;
      color: var(--text);
      letter-spacing: 0;
    }

    .review-focus-meta {
      display: flex;
      gap: 7px;
      flex-wrap: wrap;
    }

    .review-focus-meta span {
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 999px;
      padding: 5px 8px;
      color: var(--soft);
      background: rgba(0, 0, 0, 0.18);
      font-size: 0.76rem;
      font-weight: 900;
    }

    .review-graph {
      position: relative;
      grid-auto-flow: unset;
      grid-template-columns: repeat(auto-fit, minmax(12px, 1fr));
      align-items: stretch;
      height: 82px;
      min-height: 82px;
      gap: 6px;
      padding: 9px;
    }

    .review-graph::before {
      content: "";
      position: absolute;
      inset-inline: 9px;
      top: 50%;
      height: 1px;
      background: rgba(255, 248, 237, 0.22);
      pointer-events: none;
    }

    .review-graph span {
      position: relative;
      min-width: 0;
      align-self: stretch;
      height: auto;
      min-height: 0;
      border: 0;
      border-radius: 7px;
      background: transparent;
      opacity: 0.72;
      cursor: pointer;
      transform: none;
      transition: opacity 160ms ease, transform 160ms ease, box-shadow 160ms ease;
    }

    .review-graph span::before {
      content: "";
      position: absolute;
      inset-inline: 0;
      height: var(--review-eval-height, 7%);
      min-height: 4px;
      border-radius: 7px;
      background: var(--review-marker, #ffd36b);
      box-shadow: 0 0 12px color-mix(in srgb, var(--review-marker, #ffd36b), transparent 62%);
      transition: height 260ms ease, transform 160ms ease, box-shadow 160ms ease;
    }

    .review-graph span[data-review-side="white"]::before { bottom: 50%; }
    .review-graph span[data-review-side="black"]::before { top: 50%; }

    .review-graph span[aria-current="true"] {
      outline: 2px solid var(--review-marker, #ffd36b);
      outline-offset: 2px;
      opacity: 1;
      transform: scaleX(1.18);
      box-shadow: 0 0 18px color-mix(in srgb, var(--review-marker, #ffd36b), transparent 56%);
    }

    .review-eval-rail {
      position: relative;
      display: none;
      align-self: stretch;
      min-width: 26px;
      width: 26px;
      border: 1px solid rgba(255, 248, 237, 0.18);
      border-radius: 999px;
      overflow: hidden;
      background:
        linear-gradient(180deg, rgba(12, 14, 16, 0.96), rgba(25, 25, 23, 0.96));
      box-shadow:
        inset 0 0 0 1px rgba(0, 0, 0, 0.28),
        0 10px 26px rgba(0, 0, 0, 0.28);
    }

    #play.is-review-mode .review-eval-rail {
      display: block;
    }

    .review-eval-rail[hidden] {
      display: none !important;
    }

    .review-eval-fill {
      position: absolute;
      inset-inline: 0;
      bottom: 0;
      height: var(--review-white, 50%);
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), #f8f6f0 58%, #d8caa9);
      box-shadow: inset 0 10px 18px rgba(255, 255, 255, 0.3);
      transition: height 420ms cubic-bezier(.2, .9, .2, 1);
    }

    .review-eval-mid {
      position: absolute;
      inset-inline: 4px;
      top: 50%;
      height: 2px;
      border-radius: 999px;
      background: rgba(231, 182, 93, 0.72);
      box-shadow: 0 0 10px rgba(231, 182, 93, 0.32);
      transform: translateY(-50%);
    }

    .review-eval-score {
      position: absolute;
      left: 50%;
      top: 50%;
      z-index: 2;
      writing-mode: vertical-rl;
      transform: translate(-50%, -50%) rotate(180deg);
      color: #1b140d;
      font-size: 0.66rem;
      font-weight: 1000;
      text-shadow: 0 1px 4px rgba(255, 255, 255, 0.6);
      mix-blend-mode: difference;
      opacity: 0.86;
      pointer-events: none;
    }

    .review-eval-side {
      position: absolute;
      left: 50%;
      z-index: 2;
      writing-mode: vertical-rl;
      font-size: 0.58rem;
      font-weight: 1000;
      letter-spacing: 0;
      opacity: 0.72;
      pointer-events: none;
      transform: translateX(-50%) rotate(180deg);
    }

    .review-eval-black {
      top: 8px;
      color: #f8f6f0;
    }

    .review-eval-white {
      bottom: 8px;
      color: #1f1710;
    }

    .review-eval-rail[data-orientation="black"] .review-eval-fill {
      top: 0;
      bottom: auto;
    }

    .review-eval-rail[data-orientation="black"] .review-eval-white {
      top: 8px;
      bottom: auto;
    }

    .review-eval-rail[data-orientation="black"] .review-eval-black {
      top: auto;
      bottom: 8px;
    }

    .review-controls {
      display: grid;
      grid-template-columns: repeat(6, minmax(0, 1fr));
    }

    .review-controls .button {
      min-height: 42px;
      padding-inline: 8px;
    }

    .review-summary-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .review-summary-grid.is-end-summary {
      display: block;
    }

    .review-summary-grid.is-end-summary details {
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 16px;
      background: rgba(255, 248, 237, 0.045);
      overflow: hidden;
    }

    .review-summary-grid.is-end-summary summary {
      cursor: pointer;
      padding: 11px 13px;
      color: var(--gold);
      font-weight: 1000;
    }

    .review-summary-drawer-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
      padding: 0 10px 10px;
    }

    .review-key-row[hidden],
    .review-summary-grid[hidden],
    .review-move-list[hidden] {
      display: none !important;
    }

    .review-summary-card {
      min-height: 70px;
    }

    .review-move-list {
      grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
      max-height: 174px;
    }

    .review-move-chip {
      min-height: 74px;
      transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
    }

    .review-move-chip:hover,
    .review-move-chip:focus-visible {
      transform: translateY(-1px);
    }

    .review-move-chip strong {
      color: var(--text);
      text-transform: none;
    }

    .review-move-chip::after {
      color: #1b140a;
      background: var(--review-chip, rgba(255, 211, 107, 0.82));
    }

    .review-detail-stack {
      display: grid;
      gap: 8px;
    }

    .review-detail-stack details {
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 14px;
      background: rgba(255, 248, 237, 0.045);
      overflow: hidden;
    }

    .review-detail-stack summary {
      cursor: pointer;
      padding: 10px 12px;
      color: var(--gold);
      font-weight: 1000;
    }

    .review-detail-stack p {
      margin: 0;
      padding: 0 12px 12px;
      color: var(--soft);
      line-height: 1.45;
    }

    .play-square.review-from::after,
    .play-square.review-to::after {
      content: "";
      position: absolute;
      inset: 9%;
      border-radius: 16px;
      pointer-events: none;
      border: 2px solid rgba(255, 211, 107, 0.5);
      box-shadow: 0 0 16px rgba(255, 211, 107, 0.3);
      animation: reviewSquareGlow 900ms ease both;
    }

    .play-square.review-to .piece-symbol {
      animation: reviewPieceLand 300ms cubic-bezier(.2, .9, .2, 1) both;
    }

    .review-arrow-layer.is-best .review-arrow-line {
      stroke: rgba(93, 191, 255, 0.92);
      filter: drop-shadow(0 0 9px rgba(93, 191, 255, 0.38));
    }

    @keyframes reviewPanelShine {
      0%, 72% { transform: translateX(-80%); opacity: 0; }
      82% { opacity: .75; }
      100% { transform: translateX(80%); opacity: 0; }
    }

    @keyframes reviewFocusIn {
      from { opacity: 0; transform: translateY(8px) scale(.985); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }

    @keyframes reviewSquareGlow {
      from { opacity: 0; transform: scale(.86); }
      to { opacity: 1; transform: scale(1); }
    }

    @keyframes reviewPieceLand {
      from { transform: translateY(-10%) scale(.92); filter: brightness(1.25); }
      to { transform: translateY(0) scale(1); filter: none; }
    }

    @keyframes reviewGoldSpark {
      0% { box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22); }
      50% { box-shadow: 0 18px 46px rgba(0, 0, 0, 0.24), 0 0 34px rgba(255, 211, 107, 0.42); }
      100% { box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.08); }
    }

    @keyframes reviewSparkDrift {
      from { transform: translate3d(-18px, 20px, 0) rotate(0deg); opacity: 0; }
      28% { opacity: 0.7; }
      to { transform: translate3d(18px, -18px, 0) rotate(8deg); opacity: 0; }
    }

    @keyframes reviewGreenGlow {
      45% { box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22), 0 0 30px rgba(127, 214, 120, 0.42); }
    }

    @keyframes reviewOrangePulse {
      0%, 100% { border-color: color-mix(in srgb, var(--review-accent, #ffb45f), transparent 48%); }
      50% { border-color: rgba(255, 180, 95, 0.88); box-shadow: 0 0 28px rgba(255, 145, 76, 0.24); }
    }

    @keyframes reviewRedShake {
      0%, 100% { transform: translateX(0); }
      18% { transform: translateX(-5px); }
      36% { transform: translateX(5px); }
      54% { transform: translateX(-3px); }
      72% { transform: translateX(3px); }
    }

    @keyframes reviewBookFlip {
      from { transform: perspective(180px) rotateY(-72deg); opacity: 0; }
      to { transform: perspective(180px) rotateY(0); opacity: 1; }
    }

    @media (max-width: 980px) {
      .review-controls {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }
    }

    @media (max-width: 640px) {
      .post-game-actions { grid-template-columns: repeat(2, minmax(0, 1fr)); }

      .premium-review {
        padding: 12px;
        border-radius: 16px;
      }

      .premium-review-head,
      .review-focus-top,
      .review-compare-row,
      .review-summary-grid {
        grid-template-columns: 1fr;
      }

      .review-controls {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .review-move-list {
        grid-template-columns: 1fr 1fr;
        max-height: 150px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .premium-review::before,
      .review-focus-card,
      .review-focus-card::after,
      .review-quality-badge::before,
      .play-square.review-to .piece-symbol,
      .play-square.review-attack::before,
      .play-square.review-engine-to,
      .play-square.review-from::after,
      .play-square.review-to::after {
        animation: none !important;
      }
    }

    #play.is-review-mode .play-shell {
      grid-template-columns: minmax(0, 68fr) minmax(320px, 32fr);
      gap: clamp(14px, 1.8vw, 24px);
      align-items: start;
    }

    #play.is-review-mode .match-board-column {
      justify-self: stretch;
    }

    #play.is-review-mode .play-board-wrap {
