      50% {
        transform: translateY(-1px);
        box-shadow: 0 24px 54px rgba(0, 0, 0, 0.42), 0 0 0 3px rgba(255, 211, 107, 0.48), 0 0 42px rgba(255, 211, 107, 0.42);
      }
    }

