      0% {
        box-shadow: 0 12px 30px rgba(0, 0, 0, 0.28), 0 0 0 rgba(111, 168, 220, 0);
      }
      45% {
        box-shadow: 0 22px 48px rgba(0, 0, 0, 0.36), 0 0 0 2px rgba(111, 168, 220, 0.32), 0 0 34px rgba(111, 168, 220, 0.34);
      }
      100% {
