    .home-summary-card a:hover { color: var(--soft); }

    .hero {
      min-height: clamp(650px, 82svh, 860px);
      background: linear-gradient(120deg, rgba(15, 23, 42, 0.96), rgba(15, 23, 42, 0.74));
    }

    .hero::before {
      background:
        linear-gradient(90deg, rgba(15, 23, 42, 0.98) 0%, rgba(15, 23, 42, 0.88) 34%, rgba(15, 23, 42, 0.3) 78%),
        linear-gradient(135deg, rgba(34, 197, 94, 0.12), transparent 48%);
