    .hero::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      pointer-events: none;
      opacity: 0.18;
      background-image:
        linear-gradient(rgba(148, 163, 184, 0.12) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148, 163, 184, 0.12) 1px, transparent 1px);
      background-size: 56px 56px;
      -webkit-mask-image: linear-gradient(90deg, transparent 6%, #000 52%, transparent 100%);
      mask-image: linear-gradient(90deg, transparent 6%, #000 52%, transparent 100%);
