    .home-main-board-link { width: min(100%, 860px); }

    @media (max-width: 1050px) {
      .hero { min-height: auto; }
      .hero-layout { grid-template-columns: 1fr; }
      .hero-board { right: -22vw; width: min(840px, 96vw); opacity: 0.38; }
      .home-dashboard { width: min(100%, 560px); }
