    .home-feature-card::after {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      opacity: 0;
      background: linear-gradient(110deg, transparent 20%, rgba(248, 250, 252, 0.16) 48%, transparent 76%);
      transform: translateX(-105%);
      transition: opacity 180ms ease, transform 420ms ease;
