    /* Shared premium design tokens. Presentation only: no layout or route changes. */
    :root {
      --bg: #0b1220;
      --panel: #111c30;
      --panel-2: #1a2942;
      --text: #f8fafc;
      --muted: #94a3b8;
      --soft: #e2e8f0;
      --green: #22c55e;
      --green-dark: #15803d;
      --gold: #facc15;
      --blue: #60a5fa;
      --danger: #fb7185;
      --line: rgba(148, 163, 184, 0.2);
      --radius: 14px;
      --ui-radius-sm: 10px;
      --ui-radius-lg: 18px;
      --shadow: 0 20px 48px rgba(2, 6, 23, 0.32);
      --surface-shell: linear-gradient(145deg, rgba(30, 41, 59, 0.88), rgba(15, 23, 42, 0.94));
      --surface-card: linear-gradient(145deg, rgba(248, 250, 252, 0.07), rgba(30, 41, 59, 0.78) 45%, rgba(15, 23, 42, 0.92));
      --site-bg-image: radial-gradient(circle at 8% 0%, rgba(34, 197, 94, 0.12), transparent 26rem), radial-gradient(circle at 92% 4%, rgba(250, 204, 21, 0.08), transparent 24rem);
      --move-speed: 160ms;
      --ui-fast: 180ms;
      --ui-standard: 240ms;
    }

    body:not(.theme-light) {
      background-color: var(--bg);
      color: var(--text);
    }

    body:not(.theme-light) :is(.site-panel, .section-dark, .section-warm) {
      border-color: rgba(148, 163, 184, 0.14);
    }

