    .home-feature-grid { gap: 8px; }
    .home-feature-card { min-height: 62px; padding: 10px 11px; border-radius: 10px; }
    .home-feature-card strong { font-size: 0.72rem; }
    .home-feature-card small { font-size: 0.56rem; }
    .home-feature-icon { width: 28px; height: 28px; border-radius: 8px; font-size: 0.74rem; }

