    }

    .home-lower-grid { gap: 10px; }
    .home-lower-card { min-height: 172px; padding: 13px; border-radius: 11px; }
    .home-lower-card-head h3 { font-size: 0.78rem; }
    .home-lower-card-head a { font-size: 0.57rem; }
    .home-lower-game-row,
    .home-lower-tournament { margin-top: 9px; padding-block: 8px; gap: 8px; }
    .home-lower-mark { width: 31px; height: 31px; border-radius: 9px; font-size: 0.6rem; }
    .home-lower-game-row strong,
    .home-lower-tournament strong { font-size: 0.68rem; }
    .home-lower-game-row p,
    .home-lower-tournament p { font-size: 0.58rem; }
    .home-lower-footer { margin-top: 9px; font-size: 0.61rem; }
    .home-lower-rankings { margin-top: 7px; }
    .home-lower-rankings li { min-height: 32px; gap: 7px; }
    .home-lower-rankings b { font-size: 0.58rem; }
    .home-lower-rankings strong { font-size: 0.65rem; }
    .home-lower-rankings small { font-size: 0.52rem; }

    @media (max-width: 1180px) {
      .hero-command-center .hero-layout { grid-template-columns: minmax(220px, 0.8fr) minmax(410px, 1.45fr); }
    }

    @media (max-width: 820px) {
      .hero-command-center .hero-inner { width: min(100% - 24px, 680px); }
      .hero-command-center .hero-layout { grid-template-columns: 1fr; min-height: 0; }
      .hero-command-center .hero-copy { max-width: 540px; }
      .hero-stage { min-height: min(100vw, 560px); }
      .home-lower-grid { grid-template-columns: repeat(3, minmax(220px, 1fr)); }
    }

    @media (max-width: 620px) {
      .hero-command-center .hero-actions { display: grid; grid-template-columns: 1fr 1fr; }
      .hero-command-center .hero-actions .button { width: 100%; }
      .hero-stage { min-height: min(104vw, 480px); padding: 12px; }
      .hero-player-card { width: min(74%, 210px); }
      .home-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    /* Play workspace: persistent side rails around a board-first center stage. */
    @media (min-width: 1181px) {
      #play:not(.is-review-mode) {
        --play-chrome-space: 340px;
      }

      #play:not(.is-review-mode) .play-shell {
        grid-template-areas: "left center right";
        grid-template-columns: 280px minmax(0, 1fr) 360px;
        max-width: 1760px;
        gap: 16px 20px;
        align-items: start;
      }

      #play:not(.is-review-mode) .play-left-sidebar {
        grid-area: left;
        position: sticky;
        top: 82px;
        align-self: start;
        max-height: calc(100dvh - 110px);
        overflow: auto;
        overscroll-behavior: contain;
      }

      #play:not(.is-review-mode) .match-board-column {
        grid-area: center;
        min-width: 0;
      }

      #play:not(.is-review-mode) .play-right-sidebar {
        grid-area: right;
        max-height: calc(100dvh - 110px);
        overflow: auto;
        overscroll-behavior: contain;
        padding-right: 2px;
      }

      #play:not(.is-review-mode) .match-board-column > .play-bottom-actionbar {
        grid-area: actions;
        position: static;
        z-index: 8;
        padding: 9px;
        border: 1px solid rgba(255, 248, 237, 0.12);
        border-radius: 14px;
        background: rgba(23, 24, 20, 0.88);
        box-shadow: 0 14px 30px rgba(0, 0, 0, 0.22);
        backdrop-filter: blur(12px);
      }

      #play:not(.is-review-mode) .play-actions {
        grid-template-columns: minmax(154px, 1.65fr) repeat(4, minmax(0, 1fr)) auto;
      }

      #play:not(.is-review-mode) .preference-panel {
        margin: 0;
        padding: 12px;
      }

      #play:not(.is-review-mode) .play-left-sidebar .preference-grid {
        grid-template-columns: 1fr;
        gap: 7px;
      }

      #play:not(.is-review-mode) .play-left-sidebar .preference-grid > label {
        display: grid;
        grid-template-columns: 78px minmax(0, 1fr);
        align-items: center;
        gap: 8px;
        font-size: 0.76rem;
      }

      #play:not(.is-review-mode) .play-left-sidebar .preference-grid :is(select, input) {
        min-width: 0;
        min-height: 34px;
      }
    }

    @media (min-width: 700px) and (max-width: 1180px) {
      #play:not(.is-review-mode) .play-shell {
        grid-template-areas:
          "center right"
          "left right";
        grid-template-columns: minmax(0, 1fr) minmax(280px, 340px) !important;
      }

      #play:not(.is-review-mode) .play-left-sidebar { grid-area: left; }
      #play:not(.is-review-mode) .match-board-column { grid-area: center; }
      #play:not(.is-review-mode) .play-right-sidebar { grid-area: right; }
    }

    @media (max-width: 699px) {
      #play:not(.is-review-mode) .play-shell {
        grid-template-areas: "center" "right" "left";
      }

      #play:not(.is-review-mode) .play-left-sidebar,
      #play:not(.is-review-mode) .match-board-column,
      #play:not(.is-review-mode) .play-right-sidebar,
      #play:not(.is-review-mode) .play-bottom-actionbar { grid-column: 1; }

      #play:not(.is-review-mode) .play-left-sidebar { grid-area: left; }
      #play:not(.is-review-mode) .match-board-column { grid-area: center; }
      #play:not(.is-review-mode) .play-right-sidebar { grid-area: right; }
    }

    #play .play-mode-nav {
      display: grid;
      gap: 8px;
      margin-bottom: 12px;
      padding: 10px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 16px;
      background: linear-gradient(145deg, rgba(32, 38, 31, 0.82), rgba(11, 14, 17, 0.7));
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 14px 30px rgba(0, 0, 0, 0.16);
    }

    #play .play-mode-head {
      display: grid;
      gap: 2px;
      padding: 2px 3px 5px;
    }

    #play .play-mode-head strong {
      color: var(--soft);
      font-size: 0.88rem;
    }

    #play .play-mode-head small,
    #play .play-mode-card small {
      color: var(--muted);
      font-size: 0.7rem;
      font-weight: 750;
    }

    #play .play-mode-card {
      position: relative;
      display: grid;
      grid-template-columns: 34px minmax(0, 1fr) auto;
      align-items: center;
      gap: 9px;
      min-height: 58px;
      padding: 8px 9px;
      overflow: hidden;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 12px;
      color: var(--text);
      text-decoration: none;
      background: rgba(255, 255, 255, 0.035);
      transition: transform 180ms ease, border-color 180ms ease, background 180ms ease, box-shadow 180ms ease;
    }

    #play .play-mode-card::before {
      content: "";
      position: absolute;
      inset: 0;
      opacity: 0;
      pointer-events: none;
      background: linear-gradient(110deg, transparent 22%, rgba(224, 255, 191, 0.12) 50%, transparent 78%);
      transform: translateX(-120%);
      transition: opacity 180ms ease, transform 360ms ease;
    }

    #play .play-mode-card:hover,
    #play .play-mode-card:focus-visible {
      z-index: 1;
      transform: translateX(2px);
      border-color: rgba(127, 166, 80, 0.72);
      background: linear-gradient(120deg, rgba(127, 166, 80, 0.18), rgba(255, 255, 255, 0.055));
      box-shadow: 0 0 0 1px rgba(127, 166, 80, 0.16), 0 0 22px rgba(127, 166, 80, 0.16);
      outline: none;
    }

    #play .play-mode-card:hover::before,
    #play .play-mode-card:focus-visible::before {
      opacity: 1;
      transform: translateX(120%);
    }

    #play .play-mode-card > span:nth-child(2) {
      display: grid;
      min-width: 0;
      gap: 2px;
    }

    #play .play-mode-card strong {
      overflow: hidden;
      color: var(--soft);
      font-size: 0.78rem;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    #play .play-mode-icon {
      display: grid;
      width: 34px;
      height: 34px;
      place-items: center;
      border: 1px solid rgba(127, 166, 80, 0.28);
      border-radius: 10px;
      color: #d9ffc8;
      background: linear-gradient(135deg, rgba(127, 166, 80, 0.28), rgba(111, 168, 220, 0.14));
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
      font-size: 1rem;
      font-weight: 900;
    }

    #play .play-mode-card > b {
      color: var(--gold);
      font-size: 1.18rem;
      line-height: 1;
      transition: transform 180ms ease;
    }

    #play .play-mode-card:hover > b,
    #play .play-mode-card:focus-visible > b { transform: translateX(2px); }

    body:not(.friend-challenge-mode):not(.tournament-mode) #play:not(.is-review-mode) .play-mode-card[data-play-mode="ai"],
    body.friend-challenge-mode #play .play-mode-card[data-play-mode="friend"],
    body.tournament-mode #play .play-mode-card[data-play-mode="tournament"] {
      border-color: rgba(231, 182, 93, 0.72);
      background: linear-gradient(120deg, rgba(231, 182, 93, 0.18), rgba(127, 166, 80, 0.12));
      box-shadow: inset 3px 0 0 var(--gold), 0 0 18px rgba(231, 182, 93, 0.12);
    }

    /* Board-first center rail: compact live setup without competing with the board. */
    #play:not(.is-review-mode) .match-board-column,
    #play:not(.is-review-mode) .match-board-column[data-board-orientation="black"] {
      grid-template-areas:
        "setup"
        "board"
        "actions"
        "opponent"
        "player"
        "options";
    }

    #play:not(.is-review-mode) .match-board-column > .ai-player-card { grid-area: opponent; }
    #play:not(.is-review-mode) .match-board-column > .match-player-card { grid-area: player; }
    #play:not(.is-review-mode) .match-board-column > .play-board-wrap { grid-area: board; }

    #play:not(.is-review-mode) .match-board-column > .coach-setup {
      grid-area: setup;
      display: flex;
      align-items: center;
      gap: 7px;
      width: 100%;
      min-height: 44px;
      padding: 6px 8px;
      overflow-x: auto;
      border: 1px solid rgba(224, 255, 191, 0.2);
      border-radius: 14px;
      background:
        linear-gradient(115deg, rgba(127, 166, 80, 0.16), transparent 38%),
        rgba(19, 25, 22, 0.86);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 22px rgba(0, 0, 0, 0.2);
      scrollbar-width: thin;
      white-space: nowrap;
    }

    #play .coach-setup-heading {
      flex: 0 0 auto;
      padding: 0 3px;
    }

    #play .coach-setup-heading strong {
      color: var(--soft);
      font-size: 0.76rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    #play .coach-setup .coach-side-picker {
      display: inline-grid;
      flex: 0 0 auto;
      width: auto;
      grid-template-columns: repeat(2, auto);
      gap: 3px;
      padding: 2px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 9px;
      background: rgba(0, 0, 0, 0.2);
    }

    #play .coach-setup .coach-side-picker .mission-button {
      min-height: 28px;
      padding: 4px 8px;
      border: 0;
      border-radius: 6px;
      font-size: 0.7rem;
    }

    #play .play-setup-chip,
    #play .coach-setup > .badge {
      display: inline-flex;
      flex: 0 0 auto;
      align-items: center;
      min-height: 28px;
      padding: 4px 8px;
      border: 1px solid rgba(255, 248, 237, 0.1);
      border-radius: 8px;
      color: var(--muted);
      background: rgba(255, 255, 255, 0.045);
      font-size: 0.7rem;
      font-weight: 800;
      line-height: 1;
    }

    #play .coach-setup > #gameDifficultyBadge {
      color: #e1ffd1;
      border-color: rgba(127, 166, 80, 0.38);
      background: rgba(127, 166, 80, 0.16);
    }

    #play .coach-setup > #gameTurnBadge {
      color: #ffe5a6;
      border-color: rgba(231, 182, 93, 0.25);
    }

    #play .coach-difficulty-menu {
      position: relative;
      flex: 0 0 auto;
    }

    #play .coach-difficulty-menu summary {
      display: inline-flex;
      align-items: center;
      min-height: 28px;
      padding: 4px 8px;
      cursor: pointer;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 8px;
      color: var(--soft);
      background: rgba(255, 255, 255, 0.055);
      font-size: 0.7rem;
      font-weight: 850;
      list-style: none;
    }

    #play .coach-difficulty-menu summary::-webkit-details-marker { display: none; }

    #play .coach-difficulty-menu[open] .coach-levels {
      position: absolute;
      z-index: 20;
      top: calc(100% + 7px);
      right: 0;
      display: grid;
      width: min(360px, calc(100vw - 28px));
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 6px;
      padding: 8px;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 12px;
      background: rgba(20, 24, 22, 0.98);
      box-shadow: 0 16px 34px rgba(0, 0, 0, 0.32);
    }

    #play .coach-difficulty-menu:not([open]) .coach-levels { display: none; }

    #play:not(.is-review-mode) .play-board-wrap {
      border-radius: 20px;
      box-shadow: 0 0 0 1px rgba(127, 166, 80, 0.26), 0 18px 38px rgba(0, 0, 0, 0.36), 0 0 28px rgba(102, 183, 89, 0.1);
    }

    /* Compact controls live below the player frames, not in the board's primary space. */
    #play:not(.is-review-mode) .game-options-panel {
      grid-area: options;
      display: grid;
      gap: 12px;
      width: 100%;
      padding: 14px;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 18px;
      background:
        linear-gradient(120deg, rgba(127, 166, 80, 0.1), transparent 42%),
        rgba(18, 23, 21, 0.84);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.055), 0 14px 28px rgba(0, 0, 0, 0.2);
    }

    #play .game-options-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 12px;
    }

    #play .game-options-heading .section-kicker {
      margin: 0;
      color: var(--gold);
      font-size: 0.66rem;
      font-weight: 950;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    #play .game-options-heading h3 {
      margin: 0 0 0 auto;
      color: var(--soft);
      font-size: 0.92rem;
      line-height: 1;
    }

    #play .game-options-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 9px;
    }

    #play .game-options-grid label {
      display: grid;
      gap: 5px;
      min-width: 0;
      color: var(--muted);
      font-size: 0.66rem;
      font-weight: 900;
      letter-spacing: 0.035em;
      text-transform: uppercase;
    }

    #play .game-options-grid select {
      width: 100%;
      min-height: 36px;
      padding: 0 28px 0 9px;
      overflow: hidden;
      border: 1px solid rgba(255, 248, 237, 0.12);
      border-radius: 10px;
      color: var(--soft);
      background-color: rgba(0, 0, 0, 0.2);
      font: inherit;
      font-size: 0.72rem;
      font-weight: 800;
      line-height: 1;
      text-overflow: ellipsis;
      white-space: nowrap;
      transition: border-color 180ms ease, background-color 180ms ease, box-shadow 180ms ease;
    }

    #play .game-options-grid select:hover,
    #play .game-options-grid select:focus-visible {
      border-color: rgba(127, 166, 80, 0.6);
      outline: none;
      background-color: rgba(127, 166, 80, 0.1);
      box-shadow: 0 0 0 3px rgba(127, 166, 80, 0.1);
    }

    #play .game-options-panel.is-emphasized {
      border-color: rgba(231, 182, 93, 0.68);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 0 0 3px rgba(231, 182, 93, 0.12), 0 14px 28px rgba(0, 0, 0, 0.2);
    }

    @media (max-width: 699px) {
      #play:not(.is-review-mode) .match-board-column > .coach-setup {
        flex-wrap: wrap;
        overflow-x: visible;
        white-space: normal;
      }

      #play .game-options-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }

      #play .coach-difficulty-menu[open] .coach-levels { right: auto; left: 0; }
    }

    /* Dedicated player frames keep identity, stats, and live match state readable. */
    #play:not(.is-review-mode) .match-board-column > :is(.match-player-card, .ai-player-card).player-frame {
      display: grid;
      grid-template-columns: 58px minmax(0, 1fr) auto;
      grid-template-areas:
        "top top top"
        "avatar identity clock"
        "stats stats stats"
        "description description description"
        "footer footer footer";
      gap: 10px 12px;
      width: 100%;
      min-height: 216px;
      padding: 14px;
      overflow: hidden;
      border: 1px solid rgba(255, 248, 237, 0.14);
      border-radius: 18px;
      background:
        linear-gradient(125deg, rgba(255, 248, 237, 0.065), transparent 38%),
        linear-gradient(145deg, rgba(127, 166, 80, 0.1), rgba(13, 17, 15, 0.86));
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 16px 34px rgba(0, 0, 0, 0.24);
    }

    #play:not(.is-review-mode) .match-board-column > .player-frame--opponent {
      border-color: color-mix(in srgb, var(--ai-rarity) 38%, rgba(255, 248, 237, 0.12));
      background:
        linear-gradient(125deg, color-mix(in srgb, var(--ai-rarity) 10%, transparent), transparent 42%),
        linear-gradient(145deg, rgba(127, 166, 80, 0.08), rgba(13, 17, 15, 0.88));
    }

    #play .player-frame-topline {
      grid-area: top;
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 21px;
      gap: 10px;
      padding-bottom: 8px;
      border-bottom: 1px solid rgba(255, 248, 237, 0.09);
    }

    /* Player frames use their own five-row grid. This keeps legacy compact-card
       placement from collapsing identity fields into the avatar row. */
    #play:not(.is-review-mode) .match-board-column > .player-frame > :is(
      .player-frame-topline,
      .match-player-main,
      .ai-player-main,
      .match-player-timer,
      .ai-player-timer,
      .match-player-meta,
      .player-frame-stats,
      .player-frame-description,
      .player-frame-footer
    ) {
      min-width: 0;
      visibility: visible;
      opacity: 1;
    }

    #play .player-frame-kicker {
      color: var(--gold);
      font-size: 0.68rem;
      font-weight: 950;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    #play .player-frame-side,
    #play .player-frame-topline .ai-player-status {
      display: inline-flex;
      align-items: center;
      min-height: 24px;
      padding: 3px 8px;
      border: 1px solid rgba(127, 166, 80, 0.26);
      border-radius: 999px;
      color: var(--green);
      background: rgba(127, 166, 80, 0.12);
      font-size: 0.68rem;
      font-weight: 900;
      line-height: 1;
    }

    #play .player-frame--opponent.is-thinking .player-frame-topline .ai-player-status {
      color: var(--gold);
      border-color: rgba(231, 182, 93, 0.36);
      background: rgba(231, 182, 93, 0.13);
    }

    #play .player-frame > :is(.match-player-avatar, .ai-player-avatar) {
      grid-area: avatar;
      width: 58px;
      height: 58px;
      border-radius: 16px;
      font-size: 1.38rem;
    }

    #play .player-frame > :is(.match-player-main, .ai-player-main) {
      grid-area: identity;
      align-self: center;
      gap: 5px;
    }

    #play .player-frame > :is(.match-player-main, .ai-player-main) strong {
      font-size: 1rem;
    }

    #play .player-frame > :is(.match-player-timer, .ai-player-timer) {
      grid-area: clock;
      min-width: 68px;
      min-height: 36px;
      font-size: 0.82rem;
    }

    #play .player-frame-stats {
      grid-area: stats;
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 7px;
      margin: 0;
    }

    #play .player-frame-stats > div {
      min-width: 0;
      min-height: 47px;
      padding: 7px 8px;
      border: 1px solid rgba(255, 248, 237, 0.075);
      border-radius: 10px;
      background: rgba(0, 0, 0, 0.16);
    }

    #play .player-frame-stats dt {
      margin: 0;
      color: var(--muted);
      font-size: 0.62rem;
      font-weight: 800;
      line-height: 1.1;
      text-transform: uppercase;
    }

    #play .player-frame-stats dd {
      margin: 4px 0 0;
      overflow: hidden;
      color: var(--soft);
      font-size: 0.75rem;
      font-weight: 950;
      line-height: 1.15;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    #play .player-frame-description {
      grid-area: description;
      min-height: 32px;
      margin: 0;
      color: var(--muted);
      font-size: 0.75rem;
      font-weight: 700;
      line-height: 1.4;
    }

    #play .player-frame-footer,
    #play .player-frame .match-player-meta {
      grid-area: footer;
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 6px;
      min-height: 27px;
      margin: 0;
      overflow: visible;
    }

