      --cq-control-border: var(--cq-border);
      --cq-control-surface: var(--cq-surface-input);
      --cq-text-on-success: #07140f;
      --cq-control-transition: border-color var(--cq-transition-fast) ease, background-color var(--cq-transition-fast) ease, box-shadow var(--cq-transition-fast) ease, transform var(--cq-transition-fast) ease;
      --cq-component-border: var(--cq-border);
      --cq-component-surface: var(--cq-surface-panel);
      --cq-component-shadow: var(--cq-shadow-sm);
      --cq-component-padding: var(--cq-card-padding);
      --cq-status-gap: var(--cq-space-1);
      --cq-status-padding-inline: var(--cq-space-2);
      --cq-empty-state-padding: var(--cq-space-3);
    }

    :where(.cq-surface, .cq-card, .cq-control, .cq-button, .cq-field, .cq-status, .cq-empty-state, .cq-stack, .cq-cluster) {
