    .cq-surface,
    .cq-card {
      border: 1px solid var(--cq-component-border);
      border-radius: var(--cq-radius-card);
      background: var(--cq-component-surface);
      box-shadow: var(--cq-inset-highlight), var(--cq-component-shadow);
    }

    .cq-surface--elevated,
    .cq-card--elevated {
      --cq-component-surface: var(--cq-surface-panel-strong);
      --cq-component-shadow: var(--cq-shadow-md);
    }

    .cq-surface--quiet,
    .cq-card--quiet {
      --cq-component-surface: var(--cq-surface-input);
      --cq-component-shadow: none;
    }

    .cq-stack {
      display: grid;
      gap: var(--cq-component-gap, var(--cq-space-3));
    }

    .cq-cluster {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: var(--cq-component-gap, var(--cq-space-2));
    }

    .cq-control,
    .cq-button,
    .cq-field {
      border-radius: var(--cq-control-radius);
      transition: var(--cq-control-transition);
