    .cq-button {
      display: inline-flex;
      min-height: var(--cq-control-height);
      align-items: center;
      justify-content: center;
      gap: var(--cq-space-1);
      padding-inline: var(--cq-control-padding-inline);
      border: 1px solid var(--cq-control-border);
      font: inherit;
      font-weight: 700;
      line-height: 1.15;
      text-decoration: none;
    }

    .cq-button--primary { background: var(--cq-button-primary); color: var(--cq-text-primary); }
    .cq-button--secondary { background: var(--cq-button-secondary); color: var(--cq-text-primary); }
    .cq-button--success { background: var(--cq-button-success); color: var(--cq-text-on-success); }
    .cq-button--danger { background: var(--cq-button-danger); color: var(--cq-text-primary); }

    .cq-field {
      min-height: var(--cq-control-height);
      padding-inline: var(--cq-space-2);
      border: 1px solid var(--cq-control-border);
      background: var(--cq-control-surface);
      color: var(--cq-text-primary);
