  --cq-surface-raised: linear-gradient(145deg, rgba(30, 39, 79, 0.94), rgba(10, 14, 38, 0.92));
  --cq-divider: linear-gradient(90deg, transparent, var(--cq-border-strong), transparent);
  --cq-ease-premium: cubic-bezier(0.22, 1, 0.36, 1);
  --cq-card-lift-shadow: 0 20px 42px rgba(2, 6, 23, 0.28);
}

body.theme-light {
  --cq-bg-primary: #eef3fb;
  --cq-bg-secondary: #e4ebf7;
  --cq-surface: #ffffff;
  --cq-surface-elevated: #f8faff;
  --cq-surface-glass: rgba(250, 252, 255, 0.82);
  --cq-surface-glass-strong: rgba(255, 255, 255, 0.94);
  --cq-surface-panel: linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(239, 244, 254, 0.92));
  --cq-surface-panel-strong: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(233, 239, 252, 0.94));
  --cq-surface-input: rgba(246, 249, 255, 0.96);
  --cq-surface-pill: rgba(83, 101, 180, 0.1);
  --cq-text-primary: #18233d;
  --cq-text-muted: #52617d;
  --cq-text-subtle: #74819a;
  --cq-border: rgba(58, 75, 124, 0.18);
  --cq-border-strong: rgba(94, 78, 212, 0.42);
  --cq-highlight: rgba(255, 255, 255, 0.76);
  --cq-grid-line: rgba(80, 98, 160, 0.045);
  --cq-accent-primary-soft: rgba(59, 130, 246, 0.12);
  --cq-accent-secondary-soft: rgba(139, 92, 246, 0.1);
  --cq-accent-tertiary-soft: rgba(6, 182, 212, 0.12);
  --cq-card-surface: linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(239, 244, 254, 0.92));
  --cq-page-overlay: rgba(18, 32, 60, 0.12);
  --cq-surface-quiet: rgba(255, 255, 255, 0.62);
  --cq-surface-raised: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(232, 239, 253, 0.94));
  --cq-card-lift-shadow: 0 20px 42px rgba(51, 68, 117, 0.16);
}

body.theme-light {
  background:
    radial-gradient(circle at 12% -8%, rgba(139, 92, 246, 0.12), transparent 30%),
    radial-gradient(circle at 92% 4%, rgba(59, 130, 246, 0.12), transparent 28%),
