}

body.theme-light::after {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.14), rgba(214, 224, 245, 0.18));
}
body.theme-light::before {
  background-image:
    linear-gradient(var(--cq-grid-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--cq-grid-line) 1px, transparent 1px);
  background-size: 46px 46px;
  opacity: 0.5;
}

:is(body:not(.theme-light), body.theme-light) {
  color: var(--cq-text-primary);
}

:is(body:not(.theme-light), body.theme-light) main > :is(.section-dark, .section-warm) {
  position: relative;
  isolation: isolate;
  padding-block: var(--cq-section-space);
  background: transparent;
}

:is(body:not(.theme-light), body.theme-light) main > :is(.section-dark, .section-warm)::after {
  content: "";
  position: absolute;
  z-index: -1;
  right: var(--cq-page-gutter);
